Object.assign(window.TEM8_DICTIONARY, {"activated":{"oxford":{"phon":"ˈæktɪveɪt","pos":"verb","senses":[{"en":"to make sth such as a device or chemical process start working","cn":"使活动；激活；使活化"}]}},"accent":{"media":{"uk":"media/uk/accent__gb_1.mp3","us":"media/us/accent__us_1.mp3"},"oxford":{"phon":"ˈæksent","pos":"noun","senses":[{"en":"a way of pronouncing the words of a language that shows which country, area or social class a person comes from; how well somebody pronounces a particular language","cn":"口音；腔调；土音","ex":{"en":"a northern/Dublin/Scottish accent","cn":"北方／都柏林／苏格兰口音"}},{"en":"the emphasis that you should give to part of a word when saying it","cn":"重音","ex":{"en":"In ‘today’ the accent is on the second syllable.","cn":"today 一词的重音在第二音节。"}},{"en":"a mark on a letter to show that it should be pronounced in a particular way","cn":"读音符号（标在字母上）","ex":{"en":"Canapé has an accent on the ‘e’.","cn":"canapé 在 e 上面有尖音符号。"}},{"en":"a special importance that is given to something","cn":"着重点；强调","g":"[singular]","ex":{"en":"In all our products the accent is on quality.","cn":"我们的全部产品都强调质量。"}},{"en":"to emphasize a part of something","cn":"着重；强调；突出","ex":{"en":"The women accent their eyes with make-up.","cn":"女人们用化妆来突出她们的眼睛。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"腔调;口音;土音","en":"Someone who speaks with a particular accent pronounces the words of a language in a distinctive way that shows which country, region, or social class they come from.","ex":{"en":"He had developed a slight American accent.","cn":"他说话带上了一点轻微的美国口音。"}},{"pos":"N-COUNT 可数名词","cn":"（某些语言中标在字母上方的）变音符号","en":"An accent is a short line or other mark which is written above certain letters in some languages and which indicates the way those letters are pronounced."},{"pos":"N-SING 单数名词","cn":"重点;强调;关注","en":"If you put the accent on a particular feature of something, you emphasize it or give it special importance.","ex":{"en":"He is putting the accent on military readiness","cn":"他强调要保持备战状态。"}}]},"examples":[{"en":"In all our products the accent is on quality.","cn":"我们的全部产品都是强调质量。"},{"en":"Canapé has an accent on the ‘e’. * canapé","cn":"在 e 上面有尖音符号。"}]},"accordance":{"media":{"uk":"media/uk/accordance__gb_1.mp3","us":"media/us/accordance__us_1.mp3"},"oxford":{"phon":"əˈkɔːdns","pos":"noun","senses":[{"en":"( formal ) according to a rule or the way that sb says that sth should be done","cn":"依照；依据"}]},"collins":{"senses":[{"pos":"PREP-PHRASE 短语介词","cn":"按照;依据","en":"If something is done in accordance with a particular rule or system, it is done in the way that the rule or system says that it should be done.","ex":{"en":"Entries which are not in accordance with the rules will be disqualified.","cn":"不符合规定的参赛作品将被取消资格。"}}]},"examples":[{"en":"in accordance with legal requirements","cn":"根据法律要求"},{"en":"Article 47 may only be used in accordance with international law .","cn":"第47条只能按照国际法来施行。"}]},"accomplishment":{"oxford":{"phon":"əˈkʌmplɪʃmənt","pos":"noun","senses":[{"en":"an impressive thing that is done or achieved after a lot of work","cn":"成就；成绩","g":"[countable]","ex":{"en":"It was one of the President's greatest accomplishments.","cn":"那是总统最大的成就之一。"}},{"en":"a skill or special ability","cn":"才艺；技艺；专长","g":"[countable, uncountable]","ex":{"en":"Drawing and singing were among her many accomplishments.","cn":"她多才多艺，能歌善画。"}},{"en":"the successful completing of something","cn":"完成；成就","g":"[uncountable]","lab":"formal","ex":{"en":"Money will be crucial to the accomplishment of our objectives.","cn":"要实现我们的目标，钱是至关重要的。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"成就;成绩","en":"An accomplishment is something remarkable that has been done or achieved.","ex":{"en":"For a novelist, that's quite an accomplishment","cn":"对于一位小说家来说，那是相当了不起的成就。"}},{"pos":"N-COUNT 可数名词","cn":"才艺；技能；造诣","en":"Your accomplishments are the things that you can do well or the important things that you have done."},{"pos":"N-UNCOUNT 不可数名词","cn":"完成；实现","en":"The accomplishment of something is the fact of achieving or finishing it.","ex":{"en":"His function is vital to the accomplishment of the agency's mission.","cn":"要完成该机构的使命，他的作用至关重要。"}}]},"media":{"uk":"media/uk/accomplishment__gb_1.mp3","us":"media/us/accomplishment__us_1.mp3"},"examples":[{"en":"Money will be crucial to the accomplishment of our objectives.","cn":"要实现我们的目标，钱是至关重要的。"},{"en":"It was one of the President's greatest accomplishments.","cn":"那是总统最伟大的成就之一。"}]},"academy":{"media":{"uk":"media/uk/academy__gb_1.mp3","us":"media/us/academy__us_1.mp3"},"oxford":{"phon":"əˈkædəmi","pos":"noun","senses":[{"en":"a school or college for special training","cn":"专科院校","ex":{"en":"She trained at the Royal Academy of Music.","cn":"她在皇家音乐学院培训过。"}},{"en":"a type of official organization that aims to encourage and develop art, literature, science, etc.","cn":"（艺术、文学、科学等的）研究院，学会","ex":{"en":"the Royal Academy of Arts","cn":"皇家艺术学会"}},{"en":"a secondary school in Scotland","cn":"（苏格兰）中等学校，中学","ex":{"en":"He went to Ayr Academy.","cn":"他曾就读于艾尔中等学校。"}},{"en":"a private school in the US","cn":"（美国）私立学校"},{"en":"a school in England that is independent of local authority control","cn":"（英格兰不受地方政府管辖的）国立学校，国立中学"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"专科院校;学院;(美国的)私立中学","en":"Academy is sometimes used in the names of schools and colleges, especially those specializing in particular subjects or skills, or private high schools in the United States.","ex":{"en":"...the Royal Academy of Music.","cn":"皇家音乐学院"}},{"pos":"N-IN-NAMES 名称名词","cn":"（某一领域的）学会，研究院","en":"Academy appears in the names of some societies formed to improve or maintain standards in a particular field.","ex":{"en":"...the American Academy of Psychotherapists","cn":"美国心理治疗师学会"}}]},"examples":[{"en":"a police/military academy","cn":"警官/军官学校"},{"en":"the Royal Academy of Music","cn":"皇家音乐学院"}]},"acknowledges":{"oxford":{"phon":"əkˈnɒlɪdʒ","pos":"verb","senses":[{"en":"to accept that sth is true","cn":"承认（属实）"},{"en":"to accept that sb/sth has a particular authority or status","cn":"承认（权威、地位）"}]}},"activity":{"media":{"uk":"media/uk/activity__gb_1.mp3","us":"media/us/activity__us_1.mp3"},"oxford":{"phon":"ækˈtɪvəti","pos":"noun","senses":[{"en":"a thing that you do for interest or pleasure","cn":"（出于兴趣爱好而进行的）活动","g":"[countable, usually plural]","ex":{"en":"leisure/outdoor/recreational activities","cn":"休闲／户外／娱乐活动"}},{"en":"a thing that somebody does in order to achieve a particular aim","cn":"（为达到一定目的而进行的）活动","g":"[countable, usually plural]","ex":{"en":"criminal/terrorist/illegal activities","cn":"犯罪／恐怖／非法活动"}},{"en":"a situation in which something is happening or a lot of things are being done","cn":"活动；热闹状况；活跃","g":"[uncountable]","ex":{"en":"Economic activity has taken a downturn this year.","cn":"今年的经济活动有所减退。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"热闹状况;活跃","en":"Activity is a situation in which a lot of things are happening or being done.","ex":{"en":"...an extraordinary level of activity in the government bonds market.","cn":"政府公债市场异常活跃"}},{"pos":"N-COUNT 可数名词","cn":"活动","en":"An activity is something that you spend time doing.","ex":{"en":"You can take part in activities from canoeing to bird watching.","cn":"你可以参与从划独木舟到观鸟等各种活动。"}},{"pos":"N-PLURAL 复数名词","cn":"（团体为达到某种目的而采取的）活动，行动","en":"The activities of a group are the things that they do in order to achieve their aims.","ex":{"en":"...a jail term for terrorist activities","cn":"因参与恐怖活动而被判的刑期"}}]},"examples":[{"en":"The club provides a wide variety of activities including tennis, swimming and squash.","cn":"这家俱乐部的活动丰富多彩，诸如网球、游泳、壁球等。"},{"en":"The streets were noisy and full of activity.","cn":"街上熙熙攘攘，车水马龙。"}]},"accuracy":{"oxford":{"phon":"ˈækjərəsi","pos":"noun","senses":[{"en":"the state of being exact or correct; the ability to do something with skill and without making mistakes","cn":"准确（性）；精确（程度）","g":"[uncountable]","ex":{"en":"They questioned the accuracy of the information in the file.","cn":"他们怀疑档案中信息的准确性。"}},{"en":"the degree to which a measurement, calculation, etc. is exact or correct","cn":"（测量、计算等的）精确度","g":"[uncountable, countable]","ex":{"en":"the accuracy of radiocarbon dating","cn":"放射性碳定年法的精确度"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"精确（性）；准确（性）","en":"The accuracy of information or measurements is their quality of being true or correct, even in small details.","ex":{"en":"We cannot guarantee the accuracy of these figures.","cn":"我们不能保证这些数据的准确性。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"准确无误","en":"If someone or something performs a task, for example hitting a target, with accuracy, they do it in an exact way without making a mistake.","ex":{"en":"...weapons that could fire with accuracy at targets 3,000 yards away","cn":"能准确无误地击中3,000码以外目标的武器"}}]},"media":{"uk":"media/uk/accuracy__gb_1.mp3","us":"media/us/accuracy__us_1.mp3"},"examples":[{"en":"They questioned the accuracy of the information in the file.","cn":"他们怀疑档案中信息的正确性。"},{"en":"She hits the ball with great accuracy.","cn":"她击球十分准确。"}]},"acquisition":{"media":{"uk":"media/uk/acquisition__gb_1.mp3","us":"media/us/acquisition__us_1.mp3"},"oxford":{"phon":"ˌækwɪˈzɪʃn","pos":"noun","senses":[{"en":"the act of getting something, especially knowledge, a skill, etc.","cn":"（知识、技能等的）获得，得到","g":"[uncountable]","ex":{"en":"theories of child language acquisition","cn":"幼儿语言习得的理论"}},{"en":"something that somebody buys to add to what they already own, usually something valuable","cn":"（多指贵重的）购得物","g":"[countable]","ex":{"en":"His latest acquisition is a racehorse.","cn":"他最近购得一匹赛马。"}},{"en":"a company, piece of land, etc. bought by somebody, especially another company; the act of buying it","cn":"购置物；收购的公司（或产业）；购置；收购","g":"[countable, uncountable]","lab":"business","ex":{"en":"They have made acquisitions in several EU countries.","cn":"他们在几个欧盟国家购买了一些产业。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"（对公司的）收购，并购","en":"If a company or business person makes an acquisition, they buy another company or part of a company.","ex":{"en":"...the acquisition of a profitable paper recycling company.","cn":"对一家效益好的纸张回收公司的收购"}},{"pos":"N-COUNT 可数名词","cn":"购买;添置","en":"If you make an acquisition, you buy or obtain something, often to add to things that you already have.","ex":{"en":"How did you go about making this marvellous acquisition then?","cn":"那么你是怎么买到这一绝品的？"}},{"pos":"N-COUNT 可数名词","cn":"购得物;获得物;增添物","en":"You can use acquisition to refer to an object that you buy or obtain, often to add to things that you already have.","ex":{"en":"From her wardrobe Laura took her latest acquisition, a bright red dress.","cn":"劳拉从衣柜里拿出了她最近的购物战果，一件鲜红色连衣裙。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（知识、技能等的）获得，习得","en":"The acquisition of a skill or a particular type of knowledge is the process of learning it or developing it.","ex":{"en":"...language acquisition.","cn":"语言习得"}}]},"examples":[{"en":"They have made acquisitions in several EU countries.","cn":"他们在几个欧盟国家购买了一些产业。"},{"en":"His latest acquisition is a racehorse.","cn":"他最近购得一匹赛马。"}]},"accident":{"oxford":{"phon":"ˈæksɪdənt","pos":"noun","senses":[{"en":"an unpleasant event, especially in a vehicle, that happens unexpectedly and causes injury or damage","cn":"（交通）事故；意外遭遇；不测事件","g":"[countable]","ex":{"en":"a car/road/traffic accident","cn":"车祸；公路事故；交通事故"}},{"en":"something that happens unexpectedly and is not planned in advance","cn":"意外；偶然的事","g":"[countable, uncountable]","ex":{"en":"Their early arrival was just an accident.","cn":"他们早到仅仅是偶然而已。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"交通事故；车祸","en":"An accident happens when a vehicle hits a person, an object, or another vehicle, causing injury or damage.","ex":{"en":"She was involved in a serious car accident last week","cn":"上星期她卷入了一场严重的车祸。"}},{"pos":"N-COUNT 可数名词","cn":"（不幸的）意外遭遇，不测事件;事故","en":"If someone has an accident, something unpleasant happens to them that was not intended, sometimes causing injury or death.","ex":{"en":"5,000 people die every year because of accidents in the home","cn":"每年有5,000人死于家中的意外事故。"}},{"pos":"N-VAR 可变名词","cn":"意外；偶然","en":"If something happens by accident, it happens completely by chance.","ex":{"en":"She discovered the problem by accident","cn":"她碰巧发现了这个问题。"}},{"pos":"PHRASE 短语","cn":"可能发生意外的事物（或人）","en":"If you describe something or someone as an accident waiting to happen, you mean that they are likely to be a cause of danger in the future, for example because they are in poor condition or behave in an unpredictable way.","ex":{"en":"A lot of the city's buildings are accidents waiting to happen.","cn":"该城市中许多楼房都存在事故隐患。"}},{"pos":"PHRASE 短语","cn":"并非偶然;事出有因","en":"You begin a sentence with 'it's no accident' if you want to suggest that something was done deliberately or has a logical explanation, although it might give the impression of having happened by chance.","ex":{"en":"It's no accident that the boom in police series on TV coincided with the decline of the Western.","cn":"警匪剧在电视上盛行之时恰好是西部片衰退之际，这并非偶然。"}}]},"media":{"uk":"media/uk/accident__gb_1.mp3","us":"media/us/accident__us_1.mp3"},"examples":[{"en":"One in seven accidents is caused by sleepy drivers.","cn":"每七次交通事故就有一次是驾车者困倦造成的。"},{"en":"It is no accident that men fill most of the top jobs in nursing.","cn":"男人担任护理中大多数最重要的工作绝非偶然。"}]},"accumulate":{"oxford":{"phon":"əˈkjuːmjəleɪt","pos":"verb","senses":[{"en":"to gradually get more and more of something over a period of time","cn":"积累；积聚","g":"[transitive]","ex":{"en":"I seem to have accumulated a lot of books.","cn":"我好像已经收集了很多书。"}},{"en":"to gradually increase in number or quantity over a period of time","cn":"（数量）逐渐增加；（数额）逐渐增长","g":"[intransitive]","ex":{"en":"Debts began to accumulate.","cn":"债务开始增加。"}}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"堆积;积累;积聚","en":"When you accumulate things or when they accumulate, they collect or are gathered over a period of time.","ex":{"en":"Households accumulate wealth across a broad spectrum of assets","cn":"家庭在以各种各样的资产形式积累财富。"}}]},"media":{"uk":"media/uk/accumulate__gb_1.mp3","us":"media/us/accumulate__us_1.mp3"},"examples":[{"en":"By investing wisely she accumulated a fortune.","cn":"她投资精明，积累了一笔财富。"},{"en":"I seem to have accumulated a lot of books.","cn":"我好像已经收集了很多书。"}]},"acre":{"media":{"uk":"media/uk/acre__gb_1.mp3","us":"media/us/acre__us_1.mp3"},"oxford":{"phon":"ˈeɪkə(r)","pos":"noun","senses":[{"en":"a unit for measuring an area of land; 4 840 square yards or about 4 050 square metres","cn":"英亩（4 840 平方码，约为 4 050 平方米）","lab":"informal","ex":{"en":"3 000 acres of parkland","cn":"3 000 英亩开阔绿地"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"英亩（等于4,840平方码或4,047平方米）","en":"An acre is an area of land measuring 4840 square yards or 4047 square metres.","ex":{"en":"The property is set in two acres of land.","cn":"这座房产占地两英亩。"}}]},"examples":[{"en":"( informal ) Each house has acres of space around it (= a lot of space).","cn":"每座房屋四周都有大量空地。"},{"en":"3 000 acres of parkland * 3 000","cn":"英亩开阔绿地"}]},"accumulating":{"oxford":{"phon":"əˈkjuːmjəleɪt","pos":"verb","senses":[{"en":"to gradually get more and more of sth over a period of time","cn":"积累；积聚"},{"en":"to gradually increase in number or quantity over a period of time （","cn":"数量）逐渐增加；（数额）逐渐增长"}]}},"accessible":{"media":{"uk":"media/uk/accessible__gb_1.mp3","us":"media/us/accessible__us_1.mp3"},"oxford":{"phon":"əkˈsesəbl","pos":"adjective","senses":[{"en":"that can be reached, entered, used, seen, etc.","cn":"可到达的；可进入的；可使用的；可见到的","ex":{"en":"The remote desert area is accessible only by helicopter.","cn":"只有乘直升机才能进入那偏远的荒漠地区。"}},{"en":"that can be reached, entered, used, etc. by somebody who has problems walking","cn":"行动不便者可到达（或可进入、可使用等）的","ex":{"en":"accessible toilets for wheelchair users","cn":"供坐轮椅的人使用的无障碍厕所"}},{"en":"easy to understand","cn":"容易理解的；易懂的","ex":{"en":"Her poetry is always very accessible.","cn":"她的诗作总是非常通俗易懂。"}},{"en":"easy to talk to and to get to know","cn":"易接近的；易相处的；易打交道的"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"易到达的;易进入的;易够到的","en":"If a place or building is accessible to people, it is easy for them to reach it or get into it. If an object is accessible, it is easy to reach.","ex":{"en":"The Centre is easily accessible to the general public","cn":"该中心普通大众可随意进入。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"易使用的;易得到的","en":"If something is accessible to people, they can easily use it or obtain it.","ex":{"en":"The legal aid system should be accessible to more people","cn":"法律援助制度应该面向更多人。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可以理解的;易懂的","en":"If you describe a book, painting, or other work of art as accessible, you think it is good because it is simple enough for people to understand and appreciate easily.","ex":{"en":"...literary books that are accessible to a general audience.","cn":"一般读者都能欣赏的文学作品"}}]},"examples":[{"en":"The remote desert area is accessible only by helicopter.","cn":"只有乘直升机才能进入那遥远的荒漠地区。"},{"en":"a programme making science more accessible to young people","cn":"一项使科学更容易为年轻人所了解的计划"}]},"accommodation":{"media":{"uk":"media/uk/accommodation__gb_1.mp3","us":"media/us/accommodation__us_1.mp3"},"oxford":{"phon":"əˌkɒməˈdeɪʃn","pos":"noun","senses":[{"en":"a place to live, work or stay in","cn":"住处；办公处；停留处","g":"[uncountable]","lab":"British English","ex":{"en":"rented/temporary accommodation","cn":"租来的／临时的住处"}},{"en":"somewhere to live or stay, often also providing food or other services","cn":"住宿；膳宿","g":"[plural]","lab":"North American English","ex":{"en":"More and more travelers are looking for bed and breakfast accommodations in private homes.","cn":"愈来愈多的旅行者在寻找提供住宿加早餐的民宿。"}},{"en":"an agreement or arrangement between people or groups with different opinions that is acceptable to everyone; the process of reaching this agreement","cn":"和解；调解；调和","g":"[countable, uncountable]","lab":"formal","ex":{"en":"They were forced to reach an accommodation with the rebels.","cn":"他们被迫与叛乱分子达成调解协议。"}},{"en":"the way in which the lens (= a part of the eye) becomes flatter or thicker in order to create a clear image of the object that you want to look at","cn":"（眼睛）调节晶状体形状实现聚焦","g":"[uncountable]"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"住处；住所","en":"Accommodation is used to refer to buildings or rooms where people live or stay.","ex":{"en":"The government will provide temporary accommodation for up to three thousand people","cn":"政府将给多达3,000人提供临时住处。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（楼房或交通工具内的）空间，座位，铺位","en":"Accommodation is space in buildings or vehicles that is available for certain things, people, or activities.","ex":{"en":"The school occupies split-site accommodation on the main campus","cn":"该学院分散在主校区不同地点。"}},{"pos":"N-COUNT 可数名词","cn":"和解；调和","en":"An accommodation is an agreement between different people which enables them to exist together without trouble.","ex":{"en":"His instinct would be to seek a new accommodation with the nationalists","cn":"他本能的反应会是寻求与民族主义者取得新的和解。"}}]},"examples":[{"en":"More and more travelers are looking for bed and breakfast accommodations in private homes.","cn":"愈来愈多的旅行者在寻找由私人住户提供住宿加早餐的服务。"},{"en":"The building plans include much needed new office accommodation.","cn":"建筑规划包括紧缺的新办公用房在内。"}]},"achievable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可达到的；可获得的","en":"If you say that something you are trying to do is achievable, you mean that it is possible for you to succeed in doing it.","ex":{"en":"A 50% market share is achievable","cn":"50%的市场份额是可以实现的。"}}]},"media":{"uk":"media/uk/achievable__gb_1.mp3","us":"media/us/achievable__us_1.mp3"},"examples":[{"en":"Profits of $20m look achievable. * 2 000","cn":"万元的利润看来是可以完成的。"},{"en":"Profits of $20m look achievable.","cn":""}],"oxford":{"phon":"əˈtʃiːvəbl","pos":"adjective","senses":[{"en":"that can be reached, especially by making an effort for a long time","cn":"可完成的;可达到的;可实现的","ex":{"en":"Profits of $20m look achievable.","cn":"2 000 万美元的利润看来是可以完成的。"}}]}},"acquaintance":{"media":{"uk":"media/uk/acquaintance__gb_1.mp3","us":"media/us/acquaintance__us_1.mp3"},"oxford":{"phon":"əˈkweɪntəns","pos":"noun","senses":[{"en":"a person that you know but who is not a close friend","cn":"认识的人；泛泛之交；熟人","g":"[countable]","ex":{"en":"Claire has a wide circle of friends and acquaintances.","cn":"克莱尔交游很广。"}},{"en":"slight friendship","cn":"（与某人）认识，略有交情","g":"[uncountable, countable]","lab":"formal","ex":{"en":"He hoped their acquaintance would develop further.","cn":"他希望他们的交情会进一步发展。"}},{"en":"knowledge of something","cn":"（对某事物的）了解","g":"[uncountable, countable]","lab":"formal","ex":{"en":"I had little acquaintance with modern poetry.","cn":"我对现代诗所知甚少。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"认识的人；泛泛之交","en":"An acquaintance is someone who you have met and know slightly, but not well.","ex":{"en":"The proprietor was an old acquaintance of his","cn":"业主是他的一位旧相识。"}},{"pos":"N-VAR 可变名词","cn":"认识;相识","en":"If you have an acquaintance with someone, you have met them and you know them.","ex":{"en":"...a writer who becomes involved in a real murder mystery through his acquaintance with a police officer","cn":"因为认识一位警官而参与到一件真实谋杀悬案调查的作家"}},{"pos":"N-UNCOUNT 不可数名词","cn":"了解；熟悉","en":"Your acquaintance with a subject is your knowledge or experience of it.","ex":{"en":"They had little or no acquaintance with philosophy or history","cn":"他们在哲学或是历史方面几乎一无所知。"}},{"pos":"PHRASE 短语","cn":"与（某人）初次相识;结识(某人)","en":"When you make someone's acquaintance, you meet them for the first time and get to know them a little.","ex":{"en":"I first made his acquaintance in the early 1960s","cn":"我与他初次相识是在20世纪60年代早期。"}},{"pos":"PHRASE 短语","cn":"所认识的","en":"A person of your acquaintance is someone who you have met and know.","ex":{"en":"...a highly cultivated woman of our acquaintance.","cn":"我们认识的一位很有修养的女性"}}]},"examples":[{"en":"No one else of my acquaintance was as rich or successful.","cn":"我所认识的人当中，没有其他人如此富有或者成功。"},{"en":"Even on first acquaintance it was clear that he was not ‘the right type’.","cn":"初次见面就看出他显然不是“对路子的人”。"}]},"acquisitions":{"oxford":{"phon":"ˌækwɪˈzɪʃn","pos":"noun","senses":[{"en":"the act of getting sth, especially knowledge, a skill, etc. （","cn":"知识、技能等的）获得，得到"},{"en":"something that sb buys to add to what they already own, usually sth valuable （","cn":"多指贵重的）购得物"}]},"media":{"uk":"media/uk/acquisition__gb_1.mp3","us":"media/us/acquisition__us_1.mp3"}},"academics":{"oxford":{"phon":"ˌækəˈdemɪk","pos":"adjective","senses":[{"en":"connected with education, especially studying in schools and universities","cn":"学业的，教学的，学术的（尤指与学校教育有关）"},{"en":"involving a lot of reading and studying rather than practical or technical skills","cn":"学术的（与实践性、技术性相对）"}]},"media":{"uk":"media/uk/academic__gb_1.mp3","us":"media/us/academic__us_1.mp3"}},"accept":{"media":{"uk":"media/uk/accept__gb_1.mp3","us":"media/us/accept__us_1.mp3"},"oxford":{"phon":"əkˈsept","pos":"verb","senses":[{"en":"to take willingly something that is offered; to say ‘yes’ to an offer, invitation, etc.","cn":"收受；接受（建议、邀请等）","g":"[intransitive, transitive]","sc":"offer/invitation","ex":{"en":"He asked me to marry him and I accepted.","cn":"他向我求婚，我答应了。"}},{"en":"to agree to or approve of something","cn":"同意；认可","g":"[transitive]","sc":"agree","ex":{"en":"They accepted the court's decision.","cn":"他们接受法院的判决。"}},{"en":"to take payment in a particular form","cn":"接受（以某种方式支付）","g":"[transitive]","sc":"payment","ex":{"en":"This machine only accepts coins.","cn":"这台机器只收硬币。"}},{"en":"to admit that you are responsible or to blame for something","cn":"承认，承担（责任等）","g":"[transitive]","sc":"responsibility","ex":{"en":"He accepts full responsibility for what happened.","cn":"他承认对发生的事负全部责任。"}},{"en":"to continue in a difficult situation without complaining, because you realize that you cannot change it","cn":"容忍，忍受（困境等）","g":"[transitive]","sc":"difficult situation","ex":{"en":"You just have to accept the fact that we're never going to be rich.","cn":"你只得接受我们永远也富不起来这个事实。"}},{"en":"to make somebody feel welcome and part of a group","cn":"欢迎；接纳","g":"[transitive]","sc":"welcome","ex":{"en":"It may take years to be completely accepted by the local community.","cn":"也许需要多年方能被当地居民完全接纳。"}},{"en":"to believe that something is true","cn":"相信（某事属实）","g":"[transitive]","sc":"believe","ex":{"en":"I don't accept his version of events.","cn":"我不相信他对事件的说法。"}},{"en":"to allow somebody to join an organization, attend an institution, use a service, etc.","cn":"接纳，接受（为成员、会员等）","g":"[transitive]","sc":"allow somebody to join","ex":{"en":"The college he applied to has accepted him.","cn":"他申请的那所学院录取了他。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"接受;领受;收受","en":"If you accept something that you have been offered, you say yes to it or agree to take it.","ex":{"en":"Eventually Sam persuaded her to accept an offer of marriage","cn":"最终萨姆说服她接受了求婚。"}},{"pos":"VERB 动词","cn":"相信（观点、陈述、事实等）；认为…正确","en":"If you accept an idea, statement, or fact, you believe that it is true or valid.","ex":{"en":"I do not accept that there is any kind of crisis in British science","cn":"我不相信英国科学界有什么危机。"}},{"pos":"VERB 动词","cn":"赞成，同意(计划、行动等）","en":"If you accept a plan or an intended action, you agree to it and allow it to happen.","ex":{"en":"...Britain's reluctance to accept a proposal for a single European currency","cn":"英国不愿接受单一欧洲货币的建议"}},{"pos":"VERB 动词","cn":"忍受;容忍;承受","en":"If you accept an unpleasant fact or situation, you get used to it or recognize that it is necessary or cannot be changed.","ex":{"en":"People will accept suffering that can be shown to lead to a greater good","cn":"如果能证明眼前的苦难会带来更大的好处，人们就会愿意承受。"}},{"pos":"VERB 动词","cn":"承兑，认付（单据等）；认可(文件等)","en":"If a person, company, or organization accepts something such as a document, they recognize that it is genuine, correct, or satisfactory and agree to consider it or handle it.","ex":{"en":"We advised newspapers not to accept the advertising","cn":"我们建议报社不要承接这项广告。"}},{"pos":"VERB 动词","cn":"招收，接纳（求职者、会员等)","en":"If an organization or person accepts you, you are allowed to join the organization or use the services that are offered.","ex":{"en":"All-male groups will not be accepted.","cn":"清一色的男性团体将不被接纳。"}},{"pos":"VERB 动词","cn":"接纳；接受","en":"If a person or a group of people accepts you, they begin to be friendly towards you and are happy with who you are or what you do.","ex":{"en":"My grandparents have never had a problem accepting me","cn":"我的祖父母从来都是无条件地接受我。"}},{"pos":"VERB 动词","cn":"承担，承认（过失、责任等）","en":"If you accept the responsibility or blame for something, you recognize that you are responsible for it.","ex":{"en":"The company cannot accept responsibility for loss or damage.","cn":"公司不承担丢失或损坏的责任。"}},{"pos":"VERB 动词","cn":"接受，采纳(劝告、建议等）","en":"If you accept someone's advice or suggestion, you agree to do what they say.","ex":{"en":"The army refused to accept orders from the political leadership","cn":"军队拒绝接受政界领导层下达的命令。"}},{"pos":"VERB 动词","cn":"接受并使（移植器官）发挥正常功能;不排斥","en":"If someone's body accepts a transplanted organ, the organ becomes part of the body and starts to function normally.","ex":{"en":"...drugs which will fool the body into accepting transplants.","cn":"能使身体顺利接受移植器官的药物"}},{"pos":"VERB 动词","cn":"（机器）接受，适配","en":"If a machine accepts a particular kind of thing, it is designed to take it and deal with it or process it.","ex":{"en":"The telephone booths accept 10 and 20 pence coins.","cn":"电话亭可使用10便士和20便士的硬币。"}}]},"examples":[{"en":"Nothing will change as long as the workers continue to accept these appalling conditions.","cn":"只要工人继续容忍这种恶劣的劳动条件，情况就不会有任何改变。"},{"en":"It was pouring with rain so I accepted his offer of a lift.","cn":"天正下着瓢泼大雨，所以我领了他的情，搭了他的便车。"}]},"achievements":{"oxford":{"phon":"əˈtʃiːvmənt","pos":"noun","senses":[{"en":"a thing that sb has done successfully, especially using their own effort and skill","cn":"成就；成绩；功绩"},{"en":"the act or process of achieving sth","cn":"达到；完成"}]},"media":{"uk":"media/uk/achievement__gb_1.mp3","us":"media/us/achievement__us_1.mp3"}},"accomplishments":{"oxford":{"phon":"əˈkʌmplɪʃmənt","pos":"noun","senses":[{"en":"an impressive thing that is done or achieved after a lot of work","cn":"成就；成绩"},{"en":"a skill or special ability","cn":"才艺；技艺；专长"}]}},"acknowledge":{"oxford":{"phon":"əkˈnɒlɪdʒ","pos":"verb","senses":[{"en":"to accept that something is true","cn":"承认（属实）","sc":"admit","ex":{"en":"She refuses to acknowledge the need for reform.","cn":"她拒不承认改革的必要性。"}},{"en":"to accept that somebody/something has a particular authority or status","cn":"承认（权威、地位）","sc":"accept status","ex":{"en":"The country acknowledged his claim to the throne.","cn":"这个国家承认了他继承王位的权利。"}},{"en":"to tell somebody that you have received something that they sent to you","cn":"告知收悉","lab":"formal","sc":"reply to letter/email","ex":{"en":"All applications will be acknowledged.","cn":"所有的申请都将得到复函告知收悉。"}},{"en":"to show that you have noticed somebody/something by smiling, waving, etc.","cn":"（微笑、挥手等）致意","lab":"formal","sc":"smile/wave","ex":{"en":"I was standing right next to her, but she didn't even acknowledge me.","cn":"我就站在她身边，可是她理都不理我。"}},{"en":"to publicly express thanks for help you have been given","cn":"（公开）感谢","lab":"formal","sc":"express thanks","ex":{"en":"I gratefully acknowledge financial support from several local businesses.","cn":"我对几家本地企业的资助表示感谢。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"承认（事实、局面等）","en":"If you acknowledge a fact or a situation, you accept or admit that it is true or that it exists.","ex":{"en":"Naylor acknowledged, in a letter to the judge, that he was a drug addict","cn":"内勒在给法官的信中承认自己吸毒。"}},{"pos":"VERB 动词","cn":"公认，认可（某人的成就、地位、品质等）","en":"If someone's achievements, status, or qualities are acknowledged, they are known about and recognized by a lot of people, or by a particular group of people.","ex":{"en":"He is also acknowledged as an excellent goalkeeper","cn":"他也被公认为是一名出色的守门员。"}},{"pos":"VERB 动词","cn":"告知（信函等）的收到;确认…收悉","en":"If you acknowledge a message or letter, you write to the person who sent it in order to say that you have received it.","ex":{"en":"The army sent me a postcard acknowledging my request.","cn":"军队寄给我一张明信片告知我的申请书已收到。"}},{"pos":"VERB 动词","cn":"（以点头、微笑等）向…打招呼，理会","en":"If you acknowledge someone, for example by moving your head or smiling, you show that you have seen and recognized them.","ex":{"en":"He saw her but refused to even acknowledge her.","cn":"他看见了她，却连招呼也不打。"}},{"pos":"VERB 动词","cn":"（对掌声、赞扬、好意等作出姿态表示）感谢","en":"If you acknowledge someone's applause, compliments, or kindness you make a gesture in order to thank them or show your appreciation.","ex":{"en":"Doran stuck his head out of the window to acknowledge the cheering","cn":"多兰将头探出窗户向欢呼的人们致谢。"}}]},"media":{"uk":"media/uk/acknowledge__gb_1.mp3","us":"media/us/acknowledge__us_1.mp3"},"examples":[{"en":"I was standing right next to her, but she didn't even acknowledge me.","cn":"我就站在她身边，可是她理都不理我。"},{"en":"The country acknowledged his claim to the throne.","cn":"这个国家承认了他继承王位的权利。"}]},"accepting":{"oxford":{"phon":"əkˈsept","pos":"verb","senses":[{"en":"to take willingly sth that is offered; to say ‘yes’ to an offer, invitation, etc.","cn":"收受；接受（建议、邀请等）"},{"en":"to receive sth as suitable or good enough （","cn":"认为合适或足够好而）接受"}]},"media":{"uk":"media/uk/accept__gb_1.mp3","us":"media/us/accept__us_1.mp3"}},"acquires":{"oxford":{"phon":"əˈkwaɪə(r)","pos":"verb","senses":[{"en":"to gain sth by your own efforts, ability or behaviour （","cn":"通过努力、能力、行为表现）获得，得到"},{"en":"to obtain sth by buying or being given it","cn":"购得；获得；得到"}]},"media":{"uk":"media/uk/acquire__gb_1.mp3","us":"media/us/acquire__us_1.mp3"}},"access":{"media":{"uk":"media/uk/access__gb_1.mp3","us":"media/us/access__us_1.mp3"},"oxford":{"phon":"ˈækses","pos":"noun","senses":[{"en":"the opportunity or right to use something or to see somebody/something","cn":"（使用或见到的）机会，权利","ex":{"en":"High-speed internet access has become a necessity.","cn":"高速网络连接已经是必需品。"}},{"en":"a way of entering or reaching a place","cn":"通道；通路；入径","ex":{"en":"The police gained access through a broken window.","cn":"警察从一扇破窗户钻了进去。"}},{"en":"to open a computer file or use a computer system","cn":"访问；登录","lab":"computing","ex":{"en":"Most people use their phones to access the internet.","cn":"大多数人用手机上网。"},"pos":"verb"},{"en":"to be able to have or use something, especially something that you have a right to","cn":"（尤指有权）享有，使用","ex":{"en":"Being informed is the first step toward accessing better health services.","cn":"要享用更优质的医疗服务，首先要掌握相关信息。"},"pos":"verb"},{"en":"to reach, enter or use something","cn":"到达；进入；使用","g":"[often passive]","lab":"formal","ex":{"en":"The loft can be accessed by a ladder.","cn":"搭梯子可以上阁楼。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"进入（权）；通道;入径","en":"If you have access to a building or other place, you are able or allowed to go into it.","ex":{"en":"The facilities have been adapted to give access to wheelchair users.","cn":"这些设施已经改造过以方便轮椅使用者进入。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"查阅（或使用）的机会（或权利）","en":"If you have access to something such as information or equipment, you have the opportunity or right to see it or use it.","ex":{"en":"...a Code of Practice that would give patients right of access to their medical records.","cn":"允许病人查看自己病历的职业准则"}},{"pos":"N-UNCOUNT 不可数名词","cn":"接近（或面见）的机会（或权利）","en":"If you have access to a person, you have the opportunity or right to see them or meet them.","ex":{"en":"He was not allowed access to a lawyer.","cn":"他未被获准见律师。"}},{"pos":"VERB 动词","cn":"存取，访问(计算机信息）","en":"If you access something, especially information held on a computer, you succeed in finding or obtaining it.","ex":{"en":"You've illegally accessed and misused confidential security files.","cn":"你已经非法访问并盗用了机密的安全文件。"}}]},"examples":[{"en":"Disabled visitors are welcome; there is good wheelchair access to most facilities.","cn":"欢迎残疾人士参观，坐轮椅可以方便地到达多数设施。"},{"en":"Many divorced fathers only have access to their children at weekends (= they are allowed by law to see them only at weekends).","cn":"很多离婚父亲只有在周末才有权见到自己的孩子。"}]},"acquainted":{"media":{"uk":"media/uk/acquainted__gb_1.mp3","us":"media/us/acquainted__us_1.mp3"},"oxford":{"phon":"əˈkweɪntɪd","pos":"adjective","senses":[{"en":"familiar with something, having read, seen or experienced it","cn":"熟悉；了解","lab":"formal","ex":{"en":"The students are already acquainted with the work of Shakespeare.","cn":"这些学生已经读过莎士比亚的著作。"}},{"en":"not close friends with somebody, but having met a few times before","cn":"（与某人）相识，熟悉","ex":{"en":"We got acquainted at the conference (= met and started to get to know each other).","cn":"我们在那次会议上相识了。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"了解的;熟悉的","en":"If you are acquainted with something, you know about it because you have learned it or experienced it.","ex":{"en":"He was well acquainted with the literature of France, Germany and Holland","cn":"他对于法国、德国和荷兰的文学了如指掌。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（与某人）认识的，相识的","en":"If you are acquainted with someone, you have met them and you know them. You can also say that two people are acquainted.","ex":{"en":"No-one personally acquainted with the couple was permitted to talk to the Press","cn":"任何与这对夫妇有私交的人都不准和新闻界谈话。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"结识的;相互了解的","en":"If you get or become acquainted with someone that you do not know, you talk to each other or do something together so that you get to know each other. You can also say that two people get or become acquainted .","ex":{"en":"The meetings were a way to get acquainted with each other.","cn":"这些会议是一种相互结交的途径。"}}]},"examples":[{"en":"The students are already acquainted with the work of Shakespeare.","cn":"这些学生已经读过莎士比亚的著作。"},{"en":"Employees should be fully acquainted with emergency procedures.","cn":"雇员应当十分熟悉应急措施。"}]},"accurate":{"media":{"uk":"media/uk/accurate__gb_1.mp3","us":"media/us/accurate__us_1.mp3"},"oxford":{"phon":"ˈækjərət","pos":"adjective","senses":[{"en":"correct and true in every detail","cn":"正确无误的","ex":{"en":"an accurate description/picture of something","cn":"某事物精确的描述／图像"}},{"en":"able to give completely correct information or to do something in an exact way","cn":"精确的；准确的","ex":{"en":"a highly accurate electronic compass","cn":"高度精确的电子罗盘仪"}},{"en":"an accurate throw, shot, weapon, etc. hits or reaches the thing that it was aimed at","cn":"准确的（掷、射、击等）","ex":{"en":"There were only two accurate shots on goal.","cn":"只有两次射击命中目标。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（信息、测量、数据或仪器等）精确的，准确的","en":"Accurate information, measurements, and statistics are correct to a very detailed level. An accurate instrument is able to give you information of this kind.","ex":{"en":"Police have stressed that this is the most accurate description of the killer to date","cn":"警方强调这是迄今对凶手最精确的描述。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（说法、描述）确切的，恰当的","en":"An accurate statement or account gives a true or fair judgment of something.","ex":{"en":"I think it may take sometime before we can have an accurate assessment of the damage","cn":"我认为我们对损失作出准确的估算可能需要一段时间。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（行动、模仿）正确的，到位的","en":"You can use accurate to describe the results of someone's actions when they do or copy something correctly or exactly.","ex":{"en":"Marks were given for accurate spelling and punctuation.","cn":"因拼写及标点正确而得分。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（武器、投掷）精准的；（人）射击（或投掷）准的","en":"An accurate weapon or throw reaches the exact point or target that it was intended to reach. You can also describe a person as accurate if they fire a weapon or throw something in this way.","ex":{"en":"The rifle was extremely accurate","cn":"这把步枪准头极高。"}}]},"examples":[{"en":"The article accurately reflects public opinion.","cn":"文章如实反映了公众的意见。"},{"en":"Accurate records must be kept.","cn":"必须保存准确的记录。"}]},"acuity":{"media":{"uk":"media/uk/acuity__gb_1.mp3","us":"media/us/acuity__us_1.mp3"},"oxford":{"phon":"əˈkjuːəti","pos":"noun","senses":[{"en":"the ability to think, see or hear clearly","cn":"（思维、视力、听力的）敏度，敏锐","ex":{"en":"a child’s visual acuity","cn":"孩子的视力"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（视力、听力、思维的）敏锐，敏锐度","en":"Acuity is sharpness of vision or hearing, or quickness of thought.","ex":{"en":"We work on improving visual acuity.","cn":"我们致力于提高视觉的敏锐度。"}}]},"examples":[{"en":"A motorist needs good visual acuity .","cn":"驾车者需要良好的视敏度。"}]},"accredited":{"media":{"uk":"media/uk/accredited__gb_1.mp3","us":"media/us/accredited__us_1.mp3"},"oxford":{"phon":"əˈkredɪtɪd","pos":"adjective","senses":[{"en":"officially recognized as something; with official permission to be something","cn":"官方认可的；获正式承认的","ex":{"en":"our accredited representative","cn":"我们官方委任的代表"}},{"en":"officially approved as being of an accepted quality or standard","cn":"鉴定合格的；达到标准的","ex":{"en":"a fully accredited school/university/course","cn":"充分鉴定合格的学校／大学／课程"}}]},"examples":[{"en":"Only accredited journalists were allowed entry.","cn":"只有正式认可的记者才获准入内。"},{"en":"a fully accredited school/university/course","cn":"充分鉴定合格的学校/大学/课程"}]},"acquire":{"media":{"uk":"media/uk/acquire__gb_1.mp3","us":"media/us/acquire__us_1.mp3"},"oxford":{"phon":"əˈkwaɪə(r)","pos":"verb","senses":[{"en":"to gain something by your own efforts, ability or behaviour","cn":"（通过努力、能力、行为表现）获得，得到","ex":{"en":"She has acquired a good knowledge of English.","cn":"她英语已经学得很好。"}},{"en":"to obtain something by buying or being given it","cn":"购得；获得；得到","ex":{"en":"Not all of the land acquired for the road has been paid for yet.","cn":"为修路而购得的土地尚未全部付清账款。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"获得；购得","en":"If you acquire something, you buy or obtain it for yourself, or someone gives it to you.","ex":{"en":"General Motors acquired a 50% stake in Saab for about $400m","cn":"通用汽车公司以大约4亿美元的价格购得了萨博汽车公司50%的股份。"}},{"pos":"VERB 动词","cn":"获得（技能）；养成（习惯）","en":"If you acquire something such as a skill or a habit, you learn it, or develop it through your daily life or experience.","ex":{"en":"I've never acquired a taste for wine","cn":"我一向喝不惯葡萄酒。"}},{"pos":"VERB 动词","cn":"获得，得到（某种名声）","en":"If someone or something acquires a certain reputation, they start to have that reputation.","ex":{"en":"He has acquired a reputation as this country's premier solo violinist.","cn":"他已经赢得了该国首席小提琴独奏家的名誉。"}},{"pos":"PHRASE 短语","cn":"后天养成的爱好;培养出来的兴趣","en":"If you describe something as an acquired taste, you mean that a lot of people do not like it when they first experience it, but often start to like it more when they get to know it better.","ex":{"en":"Broad beans are very much an acquired taste","cn":"要慢慢适应才能吃得惯蚕豆。"}}]},"examples":[{"en":"Abstract art is an acquired taste.","cn":"要慢慢培养才会欣赏抽象艺术。"},{"en":"I have recently acquired a taste for olives.","cn":"我最近开始喜欢吃橄榄了。"}]},"acid":{"oxford":{"phon":"ˈæsɪd","pos":"noun","senses":[{"en":"a chemical, usually a liquid, that contains hydrogen and has a pH of less than seven. The hydrogen can be replaced by a metal to form a salt. Acids usually have a bitter sharp taste and can often burn holes in or damage things they touch.","cn":"酸","g":"[uncountable, countable]","lab":"chemistry","ex":{"en":"The acid burned a hole in her coat.","cn":"她的外套被酸烧了一个洞。"}},{"en":"a powerful illegal drug that affects people’s minds and makes them see and hear things that are not really there","cn":"麦角酰二乙胺；迷幻药；致幻药","g":"[uncountable]","lab":"slang","ex":{"en":"They smoke joints and drop acid.","cn":"他们抽大麻烟卷，吸食迷幻药。"}},{"en":"that contains acid or has the essential characteristics of an acid; that has a pH of less than seven","cn":"酸的；酸性的","lab":"specialist","ex":{"en":"Rye is tolerant of poor, acid soils.","cn":"黑麦耐贫瘠的酸性土壤。"},"pos":"adjective"},{"en":"that has a bitter sharp taste","cn":"酸的；酸味的","ex":{"en":"acid fruit","cn":"酸水果"},"pos":"adjective"},{"en":"critical and unkind","cn":"尖刻的；尖酸的","ex":{"en":"an acid wit","cn":"尖刻的俏皮话"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"酸","en":"An acid is a chemical substance, usually a liquid, which contains hydrogen and can react with other substances to form salts. Some acids burn or dissolve other substances that they come into contact with.","ex":{"en":"...citric acid","cn":"柠檬酸"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（物质）含酸的，酸性的","en":"An acid substance contains acid.","ex":{"en":"These shrubs must have an acid, lime-free soil.","cn":"这些灌木必须生长在不含石灰的酸性土壤环境。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（水果或饮料）酸味的，酸的","en":"An acid fruit or drink has a sour or sharp taste.","ex":{"en":"These wines may taste rather hard and somewhat acid.","cn":"这些酒可能喝着比较冲并且有股酸味。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"尖刻的；刻薄的","en":"An acid remark, or acid humour, is very unkind or critical.","ex":{"en":"This comedy of contemporary manners is told with compassion and acid humour.","cn":"这部当代风尚喜剧杂糅了悲悯的情怀和尖酸的幽默。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"麦角酰二乙胺","en":"The drug LSD is sometimes referred to as acid ."}]},"media":{"uk":"media/uk/acid__gb_1.mp3","us":"media/us/acid__us_1.mp3"},"examples":[{"en":"Rye is tolerant of poor, acid soils.","cn":"黑麦耐贫瘠的酸性土壤。"},{"en":"an acid wit","cn":"尖刻的俏皮话"}]},"accusing":{"oxford":{"phon":"əˈkjuːzɪŋ","pos":"adjective","senses":[{"en":"showing that you think somebody has done something wrong","cn":"谴责的；指责的","ex":{"en":"an accusing look/finger/tone","cn":"谴责的目光；指责的手指；责备的语调"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"谴责的;指责的;责备的","en":"If you look at someone with an accusing expression or speak to them in an accusing tone of voice, you are showing that you think they have done something wrong.","ex":{"en":"The accusing look in her eyes conveyed her sense of betrayal.","cn":"她责备的眼神中流露出一种被骗的神情。"}}]},"media":{"uk":"media/uk/accusing__gb_1.mp3","us":"media/us/accusing__us_1.mp3"},"examples":[{"en":"Her accusing eyes were fixed on him.","cn":"她用责备的眼光盯着他。"},{"en":"an accusing look/finger/tone","cn":"谴责的目光；指责的手指；责备的语调"}]},"accessibility":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to arrive at a place, especially after a long or difficult journey","cn":""},{"en":"if you get to a place, you reach it","cn":""}]},"examples":[{"en":"The island is only accessible by boat.","cn":"","src":"ld"},{"en":"There is a church which is easily accessible from my home.","cn":"","src":"ld"}],"media":{"uk":"media/uk/accessibility__gb_1.mp3","us":"media/us/accessibility__us_1.mp3"},"oxford":{"phon":"əkˌsesəˈbɪləti","pos":"noun","senses":[{"en":"how easy something is to reach, enter, use, see, etc.","cn":"可访问性：某事物到达，输入，使用，查看等的难易程度。","ex":{"en":"Data accessibility and reliability are essential factors in today's business world.","cn":"数据可访问性和可靠性是当今商业世界的重要因素。"}},{"en":"how easy something is to reach, enter, use, etc. for somebody with a disability","cn":"无障碍","ex":{"en":"The building has limited wheelchair accessibility.","cn":"该建筑的轮椅通道有限。"}},{"en":"how easy something is to understand","cn":"容易理解的；易懂的","ex":{"en":"the accessibility of her poetry","cn":"她的诗歌的易读性"}}]}},"act":{"media":{"uk":"media/uk/act__gb_1.mp3","us":"media/us/act__us_1.mp3"},"oxford":{"phon":"ækt","pos":"verb","senses":[{"en":"to do something for a particular purpose or in order to deal with a situation","cn":"做事；行动","g":"[intransitive]","sc":"do something","ex":{"en":"It is vital that we act to stop the destruction of the rainforests.","cn":"至关紧要的是，我们应当采取行动制止破坏雨林。"}},{"en":"to behave in a particular way","cn":"表现得","g":"[intransitive]","lab":"North American English","sc":"behave","ex":{"en":"The man was seen acting suspiciously.","cn":"男子看来形迹可疑。"}},{"en":"to perform a part in a play or film","cn":"扮演（戏剧、电影中的角色）","g":"[intransitive, transitive]","sc":"perform in play/film","ex":{"en":"Have you ever acted?","cn":"你演过戏吗？"}},{"en":"to pretend by your behaviour to be a particular type of person","cn":"假装","g":"[intransitive]","sc":"pretend","ex":{"en":"He's been acting the devoted husband all day.","cn":"他整天装作模范丈夫的样子。"}},{"en":"to perform a particular role or function","cn":"充当；起作用","g":"[intransitive]","sc":"perform function","ex":{"en":"She acted as an adviser to the committee.","cn":"她担任委员会的顾问。"}},{"en":"to have an effect on something","cn":"（对…）有作用，有影响","g":"[intransitive]","sc":"have effect","ex":{"en":"Alcohol acts quickly on the brain.","cn":"酒精对大脑迅速产生影响。"}},{"en":"a particular thing that somebody does","cn":"行为；行动；所为","g":"[countable]","sc":"something that somebody does","ex":{"en":"You have committed a serious criminal act.","cn":"你已经犯下严重罪行。"},"pos":"noun"},{"en":"a law that has been passed by a parliament","cn":"（议会通过的）法案，法令","g":"[countable]","sc":"law","ex":{"en":"an Act of Congress/Parliament","cn":"国会／议会法案"},"pos":"noun"},{"en":"a way of behaving that is not sincere but is intended to have a particular effect on others","cn":"假装","g":"[singular]","sc":"pretending","ex":{"en":"Don't take her seriously—it's all an act.","cn":"别跟她认真，这全是假戏一场。"},"pos":"noun"},{"en":"one of the main divisions of a play, an opera, etc.","cn":"（戏剧、歌剧等的）一幕","g":"[countable]","sc":"in play/entertainment","ex":{"en":"a play in five acts","cn":"一出五幕剧"},"pos":"noun"},{"en":"a performance, especially one of several short pieces of entertainment in a show","cn":"一段表演","g":"[countable]","sc":"in play/entertainment","ex":{"en":"a circus/comedy/magic act","cn":"马戏／喜剧／魔术表演"},"pos":"noun"},{"en":"a performer or group of musicians","cn":"表演者；音乐人组合","g":"[countable]","sc":"in play/entertainment","ex":{"en":"They were one of rock's most impressive live acts.","cn":"他们是最富感染力的现场表演摇滚乐组合之一。"},"pos":"noun"},{"en":"American College Test (an exam that some high school students take before they go to college)","cn":"美国高等院校考试（一些高中生入读高等院校前参加的考试）","pos":"abbreviation"},{"en":"Australian Capital Territory","cn":"澳大利亚首都特区","pos":"abbreviation"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"做事;行动","en":"When you act, you do something for a particular purpose.","ex":{"en":"The deaths occurred when police acted to stop widespread looting and vandalism","cn":"警方采取行动制止猖狂的打砸抢行为时有多人丧生。"}},{"pos":"VERB 动词","cn":"遵照…行动；奉行","en":"If you act on advice or information, you do what has been advised or suggested.","ex":{"en":"A patient will usually listen to the doctor's advice and act on it.","cn":"患者通常都会遵照医嘱行事。"}},{"pos":"VERB 动词","cn":"举止;表现","en":"If someone acts in a particular way, they behave in that way.","ex":{"en":"...a gang of youths who were acting suspiciously","cn":"一伙形迹可疑的年轻人"}},{"pos":"VERB 动词","cn":"起作用;充当","en":"If someone or something acts as a particular thing, they have that role or function.","ex":{"en":"He acted both as the ship's surgeon and as chaplain for the men.","cn":"他在船上为水手们兼作外科医生和牧师。"}},{"pos":"VERB 动词","cn":"假装;故作","en":"If someone acts in a particular way, they pretend to be something that they are not.","ex":{"en":"Chris acted astonished as he examined the note","cn":"克里斯检查记录时故作震惊状。"}},{"pos":"VERB 动词","cn":"代理；代表","en":"When professionals such as lawyers act for you, or act on your behalf, they are employed by you to deal with a particular matter.","ex":{"en":"...the law firm that acted for Diana during her marriage split","cn":"在戴安娜婚姻破裂期间为她做代理的法律事务所"}},{"pos":"VERB 动词","cn":"影响；作用于","en":"If a force or substance acts on someone or something, it has a certain effect on them.","ex":{"en":"He's taking a dangerous drug: it acts very fast on the central nervous system","cn":"他正在服用一种危险的药物：这种药物能很快影响到中枢神经系统。"}},{"pos":"VERB 动词","cn":"表演；演（戏）；出演（角色）","en":"If you act, or act a part in a play or film, you have a part in it.","ex":{"en":"She confessed to her parents her desire to act","cn":"她向父母坦言了自己想演戏的愿望。"}},{"pos":"N-COUNT 可数名词","cn":"行为；行动","en":"An act is a single thing that someone does.","ex":{"en":"Language interpretation is the whole point of the act of reading","cn":"阅读行为中关键在于对语言的理解。"}},{"pos":"N-SING 单数名词","cn":"装模作样;装腔作势","en":"If you say that someone's behaviour is an act, you mean that it does not express their real feelings.","ex":{"en":"There were moments when I wondered: did she do this on purpose, was it all just a game, an act?","cn":"有时我很困惑：她这么做是故意的吗？难道一切都只是一场游戏，是逢场作戏？"}},{"pos":"N-COUNT 可数名词","cn":"法案；法令；条例","en":"An Act is a law passed by the government.","ex":{"en":"...an Act of Parliament.","cn":"议会法案"}},{"pos":"N-COUNT 可数名词","cn":"（戏剧、歌剧、芭蕾舞剧等的）幕","en":"An act in a play, opera, or ballet is one of the main parts into which it is divided.","ex":{"en":"Act II contained one of the funniest scenes I have ever witnessed","cn":"第二幕里有我看过的最搞笑的场面之一。"}},{"pos":"N-COUNT 可数名词","cn":"（演出中的）短节目","en":"An act in a show is a short performance which is one of several in the show.","ex":{"en":"This year numerous bands are playing, as well as comedy acts","cn":"今年除了那些搞笑短剧外，还会有众多乐队登台献艺。"}},{"pos":"PHRASE 短语","cn":"当场抓住；抓现行","en":"If you catch someone in the act, you discover them doing something wrong or committing a crime.","ex":{"en":"The men were caught in the act of digging up buried explosives.","cn":"那些人在挖掘掩埋的爆炸物时被逮个正着。"}},{"pos":"PHRASE 短语","cn":"改邪归正；重新做人","en":"If someone who has been behaving badly cleans up their act, they start to behave in a more acceptable or responsible way.","ex":{"en":"The nation's advertisers need to clean up their act.","cn":"该国的广告商需要规范自己的行为。"}},{"pos":"PHRASE 短语","cn":"（为了得到好处等）参与，插一手","en":"If you get in on the act, you take part in or take advantage of something that was started by someone else.","ex":{"en":"In the 1970s Kodak, anxious to get in on the act, launched its own instant camera.","cn":"20世纪70年代，急于分一杯羹的柯达公司推出了自己的拍立得相机。"}},{"pos":"PHRASE 短语","cn":"正在做…","en":"You say that someone was in the act of doing something to indicate what they were doing when they were seen or interrupted.","ex":{"en":"Ken was in the act of paying his bill when Neil came up behind him.","cn":"当尼尔从后面走过来时，肯正在付账。"}},{"pos":"PHRASE 短语","cn":"全力以赴；集中精力；劲儿往一处使","en":"If you get your act together, you organize your life or your affairs so that you are able to achieve what you want or to deal with something effectively.","ex":{"en":"The Government should get its act together","cn":"政府应该集中力量。"}},{"pos":"","cn":"","en":"to act one's age→see: ; to act the fool→see: ;"},{"pos":"","cn":"","en":"相关词组：act out act up"}]},"examples":[{"en":"Acting on information from a member of the public, the police raided the club.","cn":"警察根据一个老百姓的报告，突然搜查了这家俱乐部。"},{"en":"It is vital that we act to stop the destruction of the rainforests.","cn":"至关紧要的是，我们应当采取行动制止破坏雨林。"}]},"across":{"media":{"uk":"media/uk/across__gb_1.mp3","us":"media/us/across__us_1.mp3"},"oxford":{"phon":"əˈkrɒs","pos":"preposition","senses":[{"en":"from one side to the other side of something","cn":"从…一边到另一边；横过；宽","ex":{"en":"He walked across the field.","cn":"他走过田地。"}},{"en":"on the other side of something","cn":"在…对面；在…对过","ex":{"en":"There's a bank right across the street.","cn":"街对面就有一家银行。"}},{"en":"on or over a part of the body","cn":"在（身体某部位）上","ex":{"en":"He hit him across the face.","cn":"他打了他的脸。"}},{"en":"in every part of a place, group of people, etc.","cn":"在…各处；遍及","ex":{"en":"Her family is scattered across the country.","cn":"她的家人散居全国各地。"}},{"en":"knowing a lot about something; covering or in control of something","cn":"通晓；涉及；掌握","lab":"British English","ex":{"en":"We need somebody who is across all the issues.","cn":"我们需要一个通晓所有问题的人。"}},{"en":"from one side to the other side","cn":"从一边到另一边；横过；宽","ex":{"en":"It's too wide. We can't swim across.","cn":"这太宽了，我们游不过去。"},"pos":"adverb"},{"en":"in a particular direction towards or at somebody/something","cn":"从…的一边向…","ex":{"en":"When my name was called, he looked across at me.","cn":"当叫到我名字的时候，他从那边朝我看过来。"},"pos":"adverb"},{"en":"opposite","cn":"在对面；在对过","ex":{"en":"There's a school just across from our house.","cn":"有一所学校就在我们房子对面。"},"pos":"adverb"},{"en":"written from side to side","cn":"横写的","ex":{"en":"I can't do 3 across.","cn":"我猜不出第 3 格横写的谜底。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"从一边到另一边","en":"If someone or something goes across a place or a boundary, they go from one side of it to the other.","ex":{"en":"She walked across the floor and lay down on the bed","cn":"她走过地板躺在了床上。"}},{"pos":"PREP 介词","cn":"横跨;横过;穿过","en":"If something is situated or stretched across something else, it is situated or stretched from one side of it to the other.","ex":{"en":"...the floating bridge across Lake Washington in Seattle","cn":"横跨在西雅图华盛顿湖上的浮桥"}},{"pos":"PREP 介词","cn":"（放置或覆盖）在…上","en":"If something is lying across an object or place, it is resting on it and partly covering it.","ex":{"en":"She found her clothes lying across the chair","cn":"她发现自己的衣服堆放在椅子上。"}},{"pos":"PREP 介词","cn":"在…对过；在…对面","en":"Something that is across something such as a street, river, or area is on the other side of it.","ex":{"en":"Anyone from the houses across the road could see him","cn":"马路对面房子里的任何一个人都能看见他。"}},{"pos":"ADV 副词","cn":"朝；向","en":"If you look across at a place, person, or thing, you look towards them.","ex":{"en":"He glanced across at his sleeping wife","cn":"他朝熟睡的妻子看了一眼。"}},{"pos":"PREP 介词","cn":"（表情展露）在（脸）上","en":"You use across to say that a particular expression is shown on someone's face.","ex":{"en":"An enormous grin spread across his face","cn":"他咧着大嘴笑了。"}},{"pos":"PREP 介词","cn":"（打）在（脸、头等部位）上","en":"If someone hits you across the face or head, they hit you on that part.","ex":{"en":"Graham hit him across the face with the gun.","cn":"格雷厄姆用枪击打他的脸部。"}},{"pos":"PREP 介词","cn":"在…各处；遍及","en":"When something happens across a place or organization, it happens equally everywhere within it.","ex":{"en":"The film 'Hook' opens across America on December 11","cn":"电影《铁钩船长》12月11日在美国全线上映。"}},{"pos":"PREP 介词","cn":"超越，跨越（政治、宗教、社会隔阂等）","en":"When something happens across a political, religious, or social barrier, it involves people in different groups. across the board→see: ;","ex":{"en":"...parties competing across the political spectrum","cn":"政治纷争中的各党派"}},{"pos":"ADV 副词","cn":"（测量时）宽…","en":"Across is used in measurements to show the width of something.","ex":{"en":"This hand-decorated plate measures 30cm across","cn":"这个手绘盘子直径为30厘米。"}}]},"examples":[{"en":"When my name was called, he looked across at me.","cn":"当叫到我名字的时候，他从那边朝我看过来。"},{"en":"This view is common across all sections of the community.","cn":"该社区所有阶层的人普遍持有这种看法。"}]},"academic":{"media":{"uk":"media/uk/academic__gb_1.mp3","us":"media/us/academic__us_1.mp3"},"oxford":{"phon":"ˌækəˈdemɪk","pos":"adjective","senses":[{"en":"connected with education, especially studying in schools and universities","cn":"学业的，教学的，学术的（尤指与学校教育有关）","g":"[usually before noun]","ex":{"en":"high/low academic standards","cn":"高／低学术水平"}},{"en":"involving a lot of reading and studying rather than practical or technical skills","cn":"学术性的（与实践性、技术性相对）","g":"[usually before noun]","ex":{"en":"a mixture of vocational and academic courses","cn":"职业课程和学术课程的融合"}},{"en":"good at subjects involving a lot of reading and studying","cn":"学习良好的","ex":{"en":"She wasn't very academic and hated school.","cn":"她学习不怎么样，而且讨厌上学。"}},{"en":"not connected to a real or practical situation and therefore not important","cn":"纯理论的；空谈的；学究式的","ex":{"en":"It's a purely academic question.","cn":"这是一个纯理论问题。"}},{"en":"a person who teaches and/or does research at a university or college","cn":"高等院校教师；高校科研人员","ex":{"en":"a leading/distinguished/prominent academic","cn":"一流／杰出／著名学者"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"教学的，学业的（尤指学识方面而非实践、技能上的）","en":"Academic is used to describe things that relate to the work done in schools, colleges, and universities, especially work which involves studying and reasoning rather than practical or technical skills.","ex":{"en":"Their academic standards are high","cn":"他们的教学水平很高。"}},{"pos":"ADJ 形容词","cn":"学校的;学院的;大学的","en":"Academic is used to describe things that relate to schools, colleges, and universities.","ex":{"en":"...the start of the last academic year","cn":"最后一个学年的开始"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"学术的,重研究与思辨的（与重实践或技能相对）","en":"Academic is used to describe work, or a school, college, or university, that places emphasis on studying and reasoning rather than on practical or technical skills.","ex":{"en":"The author has settled for a more academic approach","cn":"那位作者已确定采用更为学术的方法。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"学业优秀的","en":"Someone who is academic is good at studying.","ex":{"en":"The system is failing most disastrously among less academic children.","cn":"这种制度对学习不太好的孩子效果最差。"}},{"pos":"N-COUNT 可数名词","cn":"大学教师；高校科研人员","en":"An academic is a member of a university or college who teaches or does research."},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"学究式的；空谈的；不切实际的","en":"You can say that a discussion or situation is academic if you think it is not important because it has no real effect or cannot happen.","ex":{"en":"This was not an academic exercise — soldiers' lives were at risk","cn":"这不是纸上演习——士兵的生命受到了威胁。"}}]},"examples":[{"en":"The whole thing's academic now — we can't win anyway.","cn":"现在这一切都是纸上谈兵，反正我们赢不了。"},{"en":"The students return in October for the start of the new academic year.","cn":"学生于十月返校，开始新学年的学习。"}]},"acknowledged":{"oxford":{"phon":"əkˈnɒlɪdʒ","pos":"verb","senses":[{"en":"to accept that sth is true","cn":"承认（属实）"},{"en":"to accept that sb/sth has a particular authority or status","cn":"承认（权威、地位）"}]}},"accommodate":{"media":{"uk":"media/uk/accommodate__gb_1.mp3","us":"media/us/accommodate__us_1.mp3"},"oxford":{"phon":"əˈkɒmədeɪt","pos":"verb","senses":[{"en":"to provide somebody with a room or place to sleep, live or sit","cn":"提供住宿（或膳宿、座位等）","g":"[transitive]","ex":{"en":"The hotel can accommodate up to 500 guests.","cn":"这家旅馆最多可供 500 位旅客住宿。"}},{"en":"to provide enough space for somebody/something","cn":"容纳；提供空间","g":"[transitive]","ex":{"en":"The garage can accommodate three cars.","cn":"这个车库可以停放三辆车。"}},{"en":"to consider something such as somebody’s opinion or a fact and be influenced by it when you are deciding what to do or explaining something","cn":"考虑到；顾及","g":"[transitive]","lab":"formal","ex":{"en":"Our proposal tries to accommodate the special needs of minority groups.","cn":"我们的提案尽量照顾到少数群体的特殊需要。"}},{"en":"to help somebody by doing what they want","cn":"帮忙；给…提供方便","g":"[transitive]","lab":"formal","ex":{"en":"I have accommodated the press a great deal, giving numerous interviews.","cn":"我多次接受采访，已给了新闻界许多方便。"}},{"en":"to change your behaviour so that you can deal with a new situation better","cn":"顺应，适应（新情况）","g":"[intransitive, transitive]","lab":"formal","ex":{"en":"I needed to accommodate to the new schedule.","cn":"我需要适应新的时间表。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（有足够的空间）容纳，接纳","en":"If a building or space can accommodate someone or something, it has enough room for them.","ex":{"en":"The school in Poldown was not big enough to accommodate all the children","cn":"波尔登的学校不够大，容不下所有的孩子。"}},{"pos":"VERB 动词","cn":"为…提供住宿","en":"To accommodate someone means to provide them with a place to live or stay.","ex":{"en":"...a hotel built to accommodate guests for the wedding of King Alfonso","cn":"一家为接待前来参加阿方索国王婚礼的来宾而建的宾馆"}},{"pos":"VERB 动词","cn":"顾及；考虑到","en":"If something is planned or changed to accommodate a particular situation, it is planned or changed so that it takes this situation into account.","ex":{"en":"The roads are built to accommodate gradual temperature changes","cn":"修建这些道路时考虑到了温度的逐渐变化。"}},{"pos":"VERB 动词","cn":"迎合；迁就","en":"If you do something to accommodate someone, you do it with the main purpose of pleasing or satisfying them.","ex":{"en":"He has never put an arm around his wife to accommodate photographers","cn":"他从未为了迎合摄影师而搂住妻子。"}},{"pos":"VERB 动词","cn":"（调整以）适应","en":"If you accommodate to something new, you change your behaviour or ideas so that you are able to deal with it.","ex":{"en":"Some animal and plant species cannot accommodate to the rapidly changing conditions","cn":"某些种类的动植物不能适应迅速变化的环境。"}}]},"examples":[{"en":"Over 70 minutes of music can be accommodated on one CD.","cn":"一张激光唱片可以容纳 70 多分钟的音乐。"},{"en":"Our proposal tries to accommodate the special needs of minority groups.","cn":"我们的提案尽量照顾到少数群体的特殊需要。"}]},"actor":{"media":{"uk":"media/uk/actor__gb_1.mp3","us":"media/us/actor__us_1.mp3"},"oxford":{"phon":"ˈæktə(r)","pos":"noun","senses":[{"en":"a person who performs on the stage, on television or in films, especially as a profession","cn":"演员","ex":{"en":"Both lead actors (= the ones who play the main parts) are outstanding.","cn":"两位主演都很出彩。"}},{"en":"a person who plays a part, pretending by their behaviour to be a particular kind of person","cn":"（某种角色的）扮演者","ex":{"en":"I don't know if he really meant the things he said—he was always a good actor.","cn":"我不知道他说的是不是真的，他一直很会装。"}},{"en":"a participant in an action or process","cn":"（行动或过程）参与者","lab":"formal","ex":{"en":"Employers are key actors within industrial relations.","cn":"雇主在劳资关系中是关键角色。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"演员（单数形式的actor通常指男演员，但有些女演员喜欢被称为actor而不是actress)","en":"An actor is someone whose job is acting in plays or films. 'Actor' in the singular usually refers to a man, but some women who act prefer to be called 'actors' rather than 'actresses'.","ex":{"en":"His father was an actor in the Cantonese Opera Company","cn":"他的父亲是粤剧团的演员。"}}]}},"actual":{"media":{"uk":"media/uk/actual__gb_1.mp3","us":"media/us/actual__us_1.mp3"},"oxford":{"phon":"ˈæktʃuəl","pos":"adjective","senses":[{"en":"used to emphasize something that is real or exists in fact","cn":"真实的；实际的","ex":{"en":"James looks younger than his wife but in actual fact (= really) he is five years older.","cn":"詹姆斯看起来比他妻子年轻，但实际上他还大了五岁。"}},{"en":"used to emphasize the most important part of something","cn":"（强调事情最重要的部分）真正的，…本身","ex":{"en":"The rehearsal was fabulous, the actual performance even better.","cn":"彩排很精彩，实际演出更加出色。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"真实的；实际的","en":"You use actual to emphasize that you are referring to something real or genuine.","ex":{"en":"The segments are filmed using either local actors or the actual people involved","cn":"这些片断是由当地的演员或真实的当事人参与拍摄的。"}},{"pos":"ADJ 形容词","cn":"（用于对比主次方面）真正的，实际的","en":"You use actual to contrast the important aspect of something with a less important aspect.","ex":{"en":"She had compiled pages of notes, but she had not yet gotten down to doing the actual writing","cn":"她已编写了数页注释，但还未开始真正意义上的写作。"}},{"pos":"","cn":"","en":"in actual fact→see: ;"}]},"examples":[{"en":"James looks younger than his wife but in actual fact (= really) he is five years older.","cn":"詹姆斯看起来比他妻子年轻，但实际上他还大了五岁。"},{"en":"The wedding preparations take weeks but the actual ceremony takes less than an hour.","cn":"准备婚礼要几周，而婚礼仪式本身还不到一小时。"}]},"acceptable":{"media":{"uk":"media/uk/acceptable__gb_1.mp3","us":"media/us/acceptable__us_1.mp3"},"oxford":{"phon":"əkˈseptəbl","pos":"adjective","senses":[{"en":"agreed or approved of by most people in a society","cn":"（社会上）认同的，认可的","ex":{"en":"Children must learn socially acceptable behaviour.","cn":"儿童必须学会社会上认可的行为举止。"}},{"en":"that somebody agrees is of a good enough standard or allowed","cn":"可接受的；令人满意的；可容许的","ex":{"en":"For this course a pass in English at grade B is acceptable.","cn":"英语成绩达到 B 级就可以学习这门课程。"}},{"en":"not very good but good enough","cn":"还可以的；尚可的；差强人意的","ex":{"en":"The food was acceptable, but no more.","cn":"食物还可以，但说不上很好。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（大多数人）认同的，认可的","en":"Acceptable activities and situations are those that most people approve of or consider to be normal.","ex":{"en":"It is becoming more acceptable for women to drink alcohol","cn":"女性喝酒渐渐被人们接受。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"可接受的;值得接受的","en":"If something is acceptable to someone, they agree to consider it, use it, or allow it to happen.","ex":{"en":"They have thrashed out a compromise formula acceptable to Moscow","cn":"他们经过讨论达成了一项莫斯科可以接受的折中方案。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"尚可的；还可以的","en":"If you describe something as acceptable, you mean that it is good enough or fairly good.","ex":{"en":"On the far side of the street was a restaurant that looked acceptable","cn":"远处街边有一家饭店看起来还可以。"}}]},"examples":[{"en":"Air pollution in the city had reached four times the acceptable levels.","cn":"这座城市的空气污染程度曾高达可接受标准的四倍。"},{"en":"For this course a pass in English at grade B is acceptable.","cn":"英语成绩达到 B 级就可以学习这门课程。"}]},"actually":{"media":{"uk":"media/uk/actually__gb_1.mp3","us":"media/us/actually__us_1.mp3"},"oxford":{"phon":"ˈæktʃuəli","pos":"adverb","senses":[{"en":"used in speaking to emphasize a fact or a comment, or that something is really true","cn":"（在口语中用于强调事实）的确，真实地，事实上","ex":{"en":"What did she actually say?","cn":"她到底是怎么说的？"}},{"en":"used to show a contrast between what is true and what somebody believes, and to show surprise about this contrast","cn":"（表示想法与事实不一致因而惊奇）居然，竟然","ex":{"en":"It was actually kind of fun after all.","cn":"这居然还蛮有趣。"}},{"en":"used to correct somebody in a polite way","cn":"（礼貌地纠正他人）实际上，事实上","ex":{"en":"We're not American, actually. We're Canadian.","cn":"实际上我们不是美国人。我们是加拿大人。"}},{"en":"used to get somebody’s attention, to introduce a new topic or to say something that somebody may not like, in a polite way","cn":"（礼貌地引起注意、转换话题、直言）确实，说实话","ex":{"en":"Actually, I'll be a bit late home.","cn":"说真的，我回家会晚一点。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"的确;真实地;事实上","en":"You use actually to indicate that a situation exists or happened, or to emphasize that it is true.","ex":{"en":"One afternoon, I grew bored and actually fell asleep for a few minutes","cn":"一天下午，我觉得有些无聊，还真的睡着了一小会儿。"}},{"pos":"ADV 副词","cn":"（用于纠正他人或表示反对）实际上，事实上","en":"You use actually when you are correcting or contradicting someone.","ex":{"en":"No, I'm not a student. I'm a doctor, actually","cn":"不，我不是学生。实际上我是医生。"}},{"pos":"ADV 副词","cn":"(礼貌地表达与他人的期待所不同的观点)说实在的，说真的","en":"You can use actually when you are politely expressing an opinion that other people might not have expected from you.","ex":{"en":"'Do you think it's a good idea to socialize with one's patients?' — 'Actually, I do, I think it's a great idea.'","cn":"“你认为和自己的病人交朋友的想法好吗？”——“说实在的，我认为很好，这个想法很棒。”"}},{"pos":"ADV 副词","cn":"（引入新话题）其实，说实在的","en":"You use actually to introduce a new topic into a conversation.","ex":{"en":"Well actually, John, I rang you for some advice","cn":"这么说吧，约翰，我给你打电话是想得到些建议。"}}]},"examples":[{"en":"Actually, I'm busy at the moment — can I call you back?","cn":"说实在的，我这会儿正忙。我可以给你回电话吗？"},{"en":"We're not American, actually. We're Canadian.","cn":"实际上我们不是美国人。我们是加拿大人。"}]},"actively":{"oxford":{"phon":"ˈæktɪvli","pos":"adverb","senses":[{"en":"in a way that involves doing something","cn":"积极地：以一种涉及做某事的方式","ex":{"en":"Your proposal is being actively considered.","cn":"正积极考虑您的建议。"}},{"en":"in a way that involves making a determined effort and not leaving something to happen by itself","cn":"积极的","ex":{"en":"She was actively looking for a job.","cn":"她在积极找工作。"}},{"en":"in a way that has or causes an effect","cn":"积极地：以产生或引起影响的方式","ex":{"en":"Some counterfeit drugs contain actively harmful ingredients.","cn":"一些假药含有活性有害成分。"}}]},"media":{"uk":"media/uk/actively__gb_1.mp3","us":"media/us/actively__us_1.mp3"},"examples":[{"en":"Your proposal is being actively considered.","cn":"你的提议正得到认真考虑。"},{"en":"She was actively looking for a job.","cn":"她在积极找工作。"}]},"active":{"media":{"uk":"media/uk/active__gb_1.mp3","us":"media/us/active__us_1.mp3"},"oxford":{"phon":"ˈæktɪv","pos":"adjective","senses":[{"en":"always busy doing things, especially physical activities","cn":"（尤指体力上）忙碌的，活跃的","sc":"busy","ex":{"en":"Staying physically active in later years can also keep you feeling younger.","cn":"晚年保持体力活动也能够使人感觉年轻。"}},{"en":"involved in something; making a determined effort and not leaving something to happen by itself","cn":"积极的","sc":"taking part","ex":{"en":"They were both politically active.","cn":"他们两人在政治上都很积极。"}},{"en":"doing something regularly; functioning","cn":"定期进行的；起作用的","sc":"doing an activity","ex":{"en":"Numbers of sexually active teenagers have continued to rise.","cn":"有性行为的青少年人数持续增加。"}},{"en":"lively and full of ideas","cn":"活跃的；（思想上）充满活力的","sc":"lively","ex":{"en":"That child has a very active imagination.","cn":"那个小孩想象力十分丰富。"}},{"en":"working; in use or able to be used","cn":"使用中的；可以使用的","sc":"working/in use","ex":{"en":"The old watermill was active until 1960.","cn":"这台旧水磨一直用到 1960 年。"}},{"en":"having or causing a chemical effect","cn":"起化学作用的；有效的","sc":"chemical","ex":{"en":"What is the active ingredient in aspirin?","cn":"什么是阿司匹林中的有效成分？"}},{"en":"connected with a verb whose subject is the person or thing that performs the action","cn":"主动语态的","sc":"grammar","ex":{"en":"In ‘He was driving the car’, the verb is active.","cn":"在 He was driving the car 一句中，动词是主动语态。"}},{"en":"the form of a verb in which the subject is the person or thing that performs the action","cn":"主动语态","ex":{"en":"In ‘She drove the car’, ‘she’ is the subject and the verb ‘drove’ is in the active.","cn":"在“She drove the car”中，“she”是主语，动词“drove”是主动语态。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"忙碌的；活跃的","en":"Someone who is active moves around a lot or does a lot of things.","ex":{"en":"Having an active youngster about the house can be quite wearing.","cn":"家里有个好动的小孩会是相当累人的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（思想等）活跃的","en":"If you have an active mind or imagination, you are always thinking of new things.","ex":{"en":"...the tragedy of an active mind trapped by failing physical health.","cn":"因为健康状况衰退而思维受阻的悲剧"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"积极（参与）的","en":"If someone is active in an organization, cause, or campaign, they do things for it rather than just giving it their support.","ex":{"en":"...a chance for fathers to play a more active role in childcare","cn":"让父亲们更积极地参与育婴的机会"}},{"pos":"ADJ 形容词","cn":"积极的；主动的","en":"Active is used to emphasize that someone is taking action in order to achieve something, rather than just hoping for it or achieving it in an indirect way.","ex":{"en":"Companies need to take active steps to increase exports.","cn":"各公司需要采取积极措施增加出口。"}},{"pos":"ADJ 形容词","cn":"定期进行的;活动的","en":"If you say that a person or animal is active in a particular place or at a particular time, you mean that they are performing their usual activities or performing a particular activity.","ex":{"en":"Guerrilla groups are active in the province.","cn":"游击队在该省很活跃。"}},{"pos":"ADJ 形容词","cn":"（火山）活的","en":"An active volcano has erupted recently or is expected to erupt quite soon.","ex":{"en":"...molten lava from an active volcano.","cn":"活火山喷出的熔岩"}},{"pos":"ADJ 形容词","cn":"起化学(或生物)作用的;活性的;有效的","en":"An active substance has a chemical or biological effect on things.","ex":{"en":"The active ingredient in some of the mouthwashes was simply detergent.","cn":"某些漱口剂中的有效成分只不过是洗涤剂而已。"}},{"pos":"N-SING 单数名词","cn":"（语法中的）主动语态","en":"In grammar, the active or the active voice means the forms of a verb which are used when the subject refers to a person or thing that does something. For example, in 'I saw her yesterday', the verb is in the active."}]},"examples":[{"en":"In ‘He was driving the car’, the verb is active.","cn":"在 He was driving the car 一句中，动词是主动语态。"},{"en":"The parents were active in campaigning against cuts to the education budget.","cn":"学生家长积极参加反对削减教育预算的活动。"}]},"achievement":{"media":{"uk":"media/uk/achievement__gb_1.mp3","us":"media/us/achievement__us_1.mp3"},"oxford":{"phon":"əˈtʃiːvmənt","pos":"noun","senses":[{"en":"a thing that somebody has done successfully, especially using their own effort and skill","cn":"成就；成绩；功绩","g":"[countable]","ex":{"en":"the greatest scientific achievement of the decade","cn":"这十年最伟大的科学成就"}},{"en":"the act or process of achieving something","cn":"达到；完成","g":"[uncountable]","ex":{"en":"the need to raise standards of academic/educational achievement","cn":"提高学术／教育成绩标准的需要"}},{"en":"a reward that you can earn in some video games by completing a challenge or level","cn":"成就（电子游戏完成挑战或过关后得到的奖励）","g":"[countable]","ex":{"en":"If you complete the game in less than twelve hours, you are awarded an achievement at the end.","cn":"如果您在十二小时内完成游戏，您将在最后获得一项成就。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"成就;成绩;功绩","en":"An achievement is something which someone has succeeded in doing, especially after a lot of effort.","ex":{"en":"Reaching this agreement so quickly was a great achievement","cn":"如此快速达成这项协定是一大伟绩。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"完成;达到;实现","en":"Achievement is the process of achieving something.","ex":{"en":"Only the achievement of these goals will bring lasting peace.","cn":"只有达成这些目标才会带来持久的和平。"}}]},"examples":[{"en":"It was a remarkable achievement for such a young player.","cn":"如此年轻的选手有这样的成绩真是了不起。"},{"en":"Even a small success gives you a sense of achievement (= a feeling of pride).","cn":"即便是小小的成功也给人一种成就感。"}]},"account":{"media":{"uk":"media/uk/account__gb_1.mp3","us":"media/us/account__us_1.mp3"},"oxford":{"phon":"əˈkaʊnt","pos":"noun","senses":[{"en":"an arrangement that somebody has with a bank, etc. to keep money there, take some out, etc.","cn":"账户","lab":"especially in British English","sc":"at bank","ex":{"en":"I don't have a bank account.","cn":"我没有银行账户。"}},{"en":"an arrangement that somebody has with a company that allows them to use the internet, send and receive messages by email, social media, etc.","cn":"（互联网、电子邮件、社交媒体等的）账户，账号","sc":"computing","ex":{"en":"an email/a Twitter account","cn":"电子邮件／推特账户"}},{"en":"a written or spoken description of something that has happened","cn":"描述；叙述；报告","sc":"description","ex":{"en":"an eyewitness account (= a description given by somebody who saw what happened)","cn":"目击者的描述"}},{"en":"an explanation or a description of an idea, a theory or a process","cn":"（对思想、理论、过程的）解释，说明，叙述","sc":"description","ex":{"en":"the Biblical account of the creation of the world","cn":"《圣经》对创世的叙述"}},{"en":"a written record of money that is owed to a business and of money that has been paid by it","cn":"账目","g":"[usually plural]","sc":"business records","ex":{"en":"to do the accounts","cn":"记账"}},{"en":"an arrangement with a shop or business to pay bills for goods or services at a later time, for example in regular amounts every month","cn":"赊销账；赊欠账；赊购","lab":"British English also","sc":"with shop","ex":{"en":"Put it on my account please.","cn":"请记在我的赊购账上。"}},{"en":"a bill for goods or services provided over a period","cn":"账单","lab":"British English","sc":"bill","ex":{"en":"Departing guests should settle their accounts at the office.","cn":"离店客人应在服务处结账。"}},{"en":"a regular customer","cn":"老主顾","lab":"business","sc":"regular customer","ex":{"en":"The agency has lost several of its most important accounts.","cn":"这家代理机构失去了几家最重要的老客户。"}},{"en":"to have the opinion that somebody/something is a particular thing","cn":"认为是；视为","ex":{"en":"In English law a person is accounted innocent until they are proved guilty.","cn":"按英格兰法律，一个人未经证实有罪之前被视为无罪。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（银行等的）账户","en":"If you have an account with a bank or a similar organization, you have an arrangement to leave your money there and take some out when you need it.","ex":{"en":"Some banks make it difficult to open an account","cn":"一些银行把开户弄得很麻烦。"}},{"pos":"N-COUNT 可数名词","cn":"固定客户，老主顾（尤指公司）","en":"In business, a regular customer of a company can be referred to as an account, especially when the customer is another company.","ex":{"en":"Biggart Donald, the Glasgow-based marketing agency, has won two Edinburgh accounts.","cn":"比加特·唐纳德，这家驻格拉斯哥的营销代理公司已赢得了两个爱丁堡的客户。"}},{"pos":"N-COUNT 可数名词","cn":"账;账目","en":"Accounts are detailed records of all the money that a person or business receives and spends.","ex":{"en":"He kept detailed accounts.","cn":"他记明细账。"}},{"pos":"N-COUNT 可数名词","cn":"（书面或口头的）记述，描述，陈述，报告","en":"An account is a written or spoken report of something that has happened.","ex":{"en":"He gave a detailed account of what happened on the fateful night","cn":"他详细描述了那个灾难性夜晚所发生的事。"}},{"pos":"N-COUNT 可数名词","cn":"解释;说明","en":"An account of something is a theory which is intended to explain or describe it.","ex":{"en":"This basic utilitarian model gives a relatively unsophisticated account of human behaviour","cn":"这个实用的基础模型较为简略地解释了人类的行为。"}},{"pos":"VERB 动词","cn":"把…视作;认为","en":"If you say that something is accounted a particular thing, you are reporting someone's judgment or opinion that it is that thing.","ex":{"en":"The opening day of the battle was, nevertheless, accounted a success.","cn":"不过，开战的首日仍被认为是成功的。"}},{"pos":"PHRASE 短语","cn":"根据各种说法","en":"If you say that something is true by all accounts or from all accounts, you believe it is true because other people say so.","ex":{"en":"He is, by all accounts, a superb teacher.","cn":"他是位有口皆碑的好老师。"}},{"pos":"PHRASE 短语","cn":"（尽管未必大获全胜但）出色地表现（自己）","en":"If you say that someone gave a good account of themselves in a particular situation, you mean that they performed well, although they may not have been completely successful.","ex":{"en":"The team fought hard and gave a good account of themselves.","cn":"这支队伍奋力拼搏，表现出色。"}},{"pos":"PHRASE 短语","cn":"毫不重要;无足轻重","en":"If you say that something is of no account or of little account, you mean that it is very unimportant and is not worth considering.","ex":{"en":"These obscure groups were of little account in national politics.","cn":"这些名不见经传的团体在国内政界无足轻重。"}},{"pos":"PHRASE 短语","cn":"以赊账方式;以分期付款方式","en":"If you buy or pay for something on account, you pay nothing or only part of the cost at first, and pay the rest later.","ex":{"en":"He bought two bottles of vodka on account.","cn":"他挂账买了两瓶伏特加酒。"}},{"pos":"PREP-PHRASE 短语介词","cn":"因为;由于","en":"You use on account of to introduce the reason or explanation for something.","ex":{"en":"The President declined to deliver the speech himself, on account of a sore throat","cn":"总统因嗓子不适而婉拒了亲自讲话。"}},{"pos":"PHRASE 短语","cn":"从（某人的）角度；（尤指）设想处于（某人的）情况","en":"Your feelings on someone's account are the feelings you have about what they have experienced or might experience, especially when you imagine yourself to be in their situation.","ex":{"en":"Mollie told me what she'd done and I was really scared on her account.","cn":"莫莉告诉我她的所作所为，我真是替她感到后怕。"}},{"pos":"PHRASE 短语","cn":"因为（某人的）缘故","en":"If you tell someone not to do something on your account, you mean that they should do it only if they want to, and not because they think it will please you.","ex":{"en":"Don't leave on my account.","cn":"别因为我就走了。"}},{"pos":"PHRASE 短语","cn":"绝不;切勿","en":"If you say that something should on no account be done, you are emphasizing that it should not be done under any circumstances.","ex":{"en":"On no account should the mixture boil.","cn":"切勿让这种混合物沸腾。"}},{"pos":"PHRASE 短语","cn":"为了那个/这个缘故","en":"You can use on that account or on this account when you want to say that something happens for the reason you have just mentioned.","ex":{"en":"Wine is radioactive but few people stop drinking it on that account.","cn":"酒是有放射性的，可是很少有人因此而戒酒。"}},{"pos":"PHRASE 短语","cn":"根据(某人)自己的说法","en":"If you say that something concerning a particular person is true by his or her own account, you mean that you believe it because that person has said it is true.","ex":{"en":"He was by his own account an ambitious workaholic.","cn":"据他自己所言，他是个雄心勃勃的工作狂。"}},{"pos":"PHRASE 短语","cn":"作为个人地；为自身利益地","en":"If you take part in a business activity on your own account, you do it for yourself, and not as a representative or employee of a company.","ex":{"en":"She had plans to set up in business on her own account.","cn":"她计划自己创业。"}},{"pos":"PHRASE 短语","cn":"自主自愿地;责任自负地","en":"If you do something on your own account, you do it because you want to and without being asked, and you take responsibility for your own action.","ex":{"en":"I told him if he withdrew it was on his own account.","cn":"我告诉他，如果他退出，责任自负。"}},{"pos":"PHR-RECIP 相互短语","cn":"（与敌人或对手）决战，算账，了结恩怨","en":"To settle accounts with an enemy or opponent means to bring your fight or quarrel to an end by defeating them.","ex":{"en":"...until the great day came when the Germans could finally settle accounts with the British","cn":"直到德国人最终能和英国人清算旧账的重大日子的来临"}},{"pos":"PHRASE 短语","cn":"考虑到；把…计算在内","en":"If you take something into account, or take account of something, you consider it when you are thinking about a situation or deciding what to do.","ex":{"en":"The defendant asked for 21 similar offences to be taken into account","cn":"被告要求考虑到类似的21起违法行为的情况。"}},{"pos":"PHRASE 短语","cn":"（对所做的错事）被要求解释并遭斥责，被问责","en":"If someone is called, held, or brought to account for something they have done wrong, they are made to explain why they did it, and are often criticized or punished for it.","ex":{"en":"Ministers should be called to account for their actions.","cn":"部长们应该对他们的行为作出解释。"}},{"pos":"","cn":"","en":"相关词组：account for"}]},"examples":[{"en":"In English law a person is accounted innocent until they are proved guilty.","cn":"按英格兰法律，一个人未经证实有罪之前被视为无罪。"},{"en":"The company takes account of environmental issues wherever possible.","cn":"这家公司总是尽量考虑到各方面的环境问题。"}]},"academically":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is educated is intelligent and knows a lot because they have had a good education, have read a lot etc","cn":""},{"en":"an intelligent, well-educated person who spends a lot of their time thinking about, writing about, and discussing ideas, literature etc","cn":""}]},"examples":[{"en":"He possessed no academic qualifications.","cn":"","src":"ld"},{"en":"a program to raise academic standards","cn":"","src":"ld"}],"media":{"uk":"media/uk/academically__gb_1.mp3","us":"media/us/academically__us_1.mp3"},"oxford":{"phon":"ˌækəˈdemɪkli","pos":"adverb","senses":[{"en":"in a way that is connected with education, especially studying in schools and universities","cn":"学业的，教学的，学术的（尤指与学校教育有关）","ex":{"en":"You have to do well academically to get into medical school.","cn":"你得学习成绩优良才能入读医学院。"}},{"en":"in a way that involves a lot of reading and studying rather than practical or technical skills","cn":"学术性的（与实践性、技术性相对）","ex":{"en":"He wasn’t very well qualified academically but had a lot of experience.","cn":"他的学术水平不高，但经验丰富。"}}]}},"accurately":{"oxford":{"phon":"ˈækjərətli","pos":"adverb","senses":[{"en":"in a way that is correct and true in every detail","cn":"正确无误地","ex":{"en":"The article accurately reflects public opinion.","cn":"这篇文章如实反映了公众的意见。"}},{"en":"in an exact way","cn":"精确地；准确地","ex":{"en":"Quantities must be measured accurately.","cn":"数量的计量必须准确。"}},{"en":"hitting or reaching the thing that was aimed at","cn":"准确地（掷、射、击等）","ex":{"en":"You need to hit the ball accurately.","cn":"你必须准确击球。"}}]},"media":{"uk":"media/uk/accurately__gb_1.mp3","us":"media/us/accurately__us_1.mp3"},"examples":[{"en":"The article accurately reflects public opinion.","cn":"文章如实反映了公众的意见。"},{"en":"You need to hit the ball accurately.","cn":"你必须准确击球。"}]},"acknowledging":{"oxford":{"phon":"əkˈnɒlɪdʒ","pos":"verb","senses":[{"en":"to accept that sth is true","cn":"承认（属实）"},{"en":"to accept that sb/sth has a particular authority or status","cn":"承认（权威、地位）"}]}},"acting":{"media":{"uk":"media/uk/acting__gb_1.mp3","us":"media/us/acting__us_1.mp3"},"oxford":{"phon":"ˈæktɪŋ","pos":"noun","senses":[{"en":"the activity or profession of performing in plays, films, etc.","cn":"（戏剧、电影等中的）表演；演艺业","ex":{"en":"She started her acting career while still at school.","cn":"上学时她就开始了自己的演艺事业。"}},{"en":"doing the work of another person for a short time","cn":"临时代理的","ex":{"en":"the acting manager","cn":"代理经理"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"表演;演艺业;演技;演戏","en":"Acting is the activity or profession of performing in plays or films.","ex":{"en":"She pursued an acting career after four years of modelling.","cn":"当了4年的模特之后她踏上了演艺之路。"}},{"pos":"ADJ 形容词","cn":"临时代理的","en":"You use acting before the title of a job to indicate that someone is doing that job temporarily.","ex":{"en":"...the new acting President.","cn":"新任代总统"}}]},"examples":[{"en":"the acting manager","cn":"代理经理"}]},"acceptance":{"media":{"uk":"media/uk/acceptance__gb_1.mp3","us":"media/us/acceptance__us_1.mp3"},"oxford":{"phon":"əkˈseptəns","pos":"noun","senses":[{"en":"the act of accepting a gift, an invitation, an offer, etc.","cn":"接受（礼物、邀请、建议等）","g":"[uncountable, countable]","ex":{"en":"Please confirm your acceptance of this offer in writing.","cn":"请书面确认你接受这项建议。"}},{"en":"the act of agreeing with something and approving of it","cn":"同意；认可","g":"[uncountable]","ex":{"en":"The new laws have gained widespread acceptance.","cn":"新法律获得广泛赞同。"}},{"en":"the process of allowing somebody to join something or be a member of a group","cn":"接纳，接受（为成员、会员等）","g":"[uncountable]","ex":{"en":"Your acceptance into the insurance plan is guaranteed.","cn":"你参加保险计划一事已有保证。"}},{"en":"the quality of being willing to accept an unpleasant or difficult situation","cn":"无怨接受（逆境、困境等）；逆来顺受","g":"[uncountable]","ex":{"en":"acceptance of death/suffering","cn":"接受死亡／苦难"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"接受;赞同","en":"Acceptance of an offer or a proposal is the act of saying yes to it or agreeing to it.","ex":{"en":"The Party is being degraded by its acceptance of secret donations","cn":"该党因私下接受捐赠而蒙羞。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"相信；承认","en":"If there is acceptance of an idea, most people believe or agree that it is true.","ex":{"en":"...a theory that is steadily gaining acceptance","cn":"逐步得到承认的理论"}},{"pos":"N-UNCOUNT 不可数名词","cn":"忍受;容忍;承受","en":"Your acceptance of a situation, especially an unpleasant or difficult one, is an attitude or feeling that you cannot change it and that you must get used to it.","ex":{"en":"Popular acceptance of authority had been an early aim of the Nationalists.","cn":"国家主义者的一个早期目标是推动民众对权威的接受。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（对新产品的）接受，认可","en":"If there is acceptance of a new product, people start to like it and get used to it.","ex":{"en":"Car manufacturers are already producing small numbers of electric vehicles to test customer acceptance","cn":"汽车制造商们已经开始生产少量的电动车辆以测试顾客的接受程度。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"接纳;欢迎","en":"Acceptance of someone into a group means beginning to think of them as part of the group and to act in a friendly way towards them.","ex":{"en":"...an effort to ensure that the disabled achieve real acceptance.","cn":"为确保残疾人真正得到接纳而作出的努力"}}]},"examples":[{"en":"Social acceptance is important for most young people.","cn":"对大多数青年来说，重要的是要为社会所接纳。"},{"en":"Your acceptance into the insurance plan is guaranteed.","cn":"你参加保险计划一事已有保证。"}]},"ac":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"交流电","en":"AC is used to refer to an electric current that continually changes direction as it flows. AC is an abbreviation for (缩略=) 'alternating current'.","ex":{"en":"In Europe, AC is usually generated at 50 Hz.","cn":"欧洲的交流电输出频率通常为50赫兹。"}}]},"media":{"uk":"media/uk/ac__gb_1.mp3","us":"media/us/ac__us_1.mp3"},"oxford":{"phon":"ˌeɪ ˈsiː","pos":"abbreviation","senses":[{"en":"air conditioning","cn":"空气调节系统","lab":"especially North American English"},{"en":"alternating current","cn":"交流；交流电流"}]}},"action":{"media":{"uk":"media/uk/action__gb_1.mp3","us":"media/us/action__us_1.mp3"},"oxford":{"phon":"ˈækʃn","pos":"noun","senses":[{"en":"the process of doing something in order to make something happen or to deal with a situation","cn":"行动；行为过程","g":"[uncountable]","sc":"what somebody does","ex":{"en":"The time has come for action if these beautiful animals are to survive.","cn":"若要使这些美丽的动物能生存下去，现在就要行动起来。"}},{"en":"a thing that somebody does","cn":"所做之事；行为","g":"[countable]","sc":"what somebody does","ex":{"en":"Each of us must take responsibility for our own actions.","cn":"我们每个人都必须对自己的行为负责。"}},{"en":"things that workers do, especially stopping work, to protest to their employers about something","cn":"（尤指罢工等）劳工行动","g":"[uncountable, countable]","sc":"stopping work","ex":{"en":"Workers voted in favour of strike action.","cn":"工人表决支持罢工。"}},{"en":"a legal process to stop a person or company from doing something, or to make them pay for a mistake, etc.","cn":"诉讼；起诉","g":"[countable, uncountable]","sc":"legal process","ex":{"en":"A libel action is being brought against the magazine that published the article.","cn":"刊登该文章的杂志将被起诉诽谤。"}},{"en":"fighting in a battle or war","cn":"战斗；作战","g":"[uncountable]","sc":"in war","ex":{"en":"The possibility of taking military action has not been ruled out.","cn":"不排除采取军事行动的可能性。"}},{"en":"the events in a story, play, etc.","cn":"（故事、戏剧等中的）情节","g":"[uncountable]","sc":"in story/play","ex":{"en":"The action takes place in France.","cn":"这个故事发生在法国。"}},{"en":"exciting events","cn":"激动人心的事","g":"[uncountable]","sc":"exciting events","ex":{"en":"I like films with plenty of action.","cn":"我喜欢情节曲折离奇的影片。"}},{"en":"the effect that something such as a chemical has on something","cn":"（一种物质或化学品对另一种所起的）作用","g":"[uncountable]","sc":"effect","ex":{"en":"Vitamin D can be made in the body by the action of sunlight on the skin.","cn":"维生素D可以通过阳光对皮肤的作用在人体内产生。"}},{"en":"the way a part of the body moves or functions","cn":"（身体部位的）动作，功能","g":"[uncountable, countable]","lab":"specialist","sc":"of part of the body","ex":{"en":"a study of the action of the liver","cn":"对肝功能的研究"}},{"en":"the mechanical parts of a piano, gun, clock, etc. or the way the parts move","cn":"（钢琴、枪炮、钟表等的）机械装置，活动部件；（机械部件的）活动方式","g":"[singular]","sc":"of machine"},{"en":"to make sure that something is done or dealt with","cn":"务必做，确保处理（某事）","ex":{"en":"Your request will be actioned.","cn":"你的要求会处理的。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"行动；措施","en":"Action is doing something for a particular purpose.","ex":{"en":"The government is taking emergency action to deal with a housing crisis","cn":"政府正采取紧急措施解决住房危机。"}},{"pos":"N-COUNT 可数名词","cn":"所做之事；行为","en":"An action is something that you do on a particular occasion.","ex":{"en":"As always, Peter had a reason for his action","cn":"一如往常，彼得对自己的行为总有说辞。"}},{"pos":"N-COUNT 可数名词","cn":"诉讼；起诉","en":"To bring a legal action against someone means to bring a case against them in a court of law.","ex":{"en":"Two leading law firms are to prepare legal actions against tobacco companies.","cn":"两家很有名的律师事务所准备向烟草公司提起诉讼。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（化学物质产生的）作用，效果","en":"The action of a chemical is the way in which it works, or the effects that it has.","ex":{"en":"Her description of the nature and action of poisons is amazingly accurate.","cn":"他对一些毒药的性质和作用的描述惊人地准确。"}},{"pos":"N-SING 单数名词","cn":"激动人心（或重要）的大事","en":"The action is all the important and exciting things that are happening in a situation.","ex":{"en":"Hollywood is where the action is now.","cn":"好莱坞如今风头正盛。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"战斗；作战","en":"The fighting which takes place in a war can be referred to as action .","ex":{"en":"Leaders in America have generally supported military action","cn":"美国领导人普遍支持采取军事行动。"}},{"pos":"ADJ 形容词","cn":"（电影）情节惊险刺激的；动作（片）的；动作片中的","en":"An action movie is a film in which a lot of dangerous and exciting things happen. An action hero is the main character in one of these films.","ex":{"en":"Stallone wants to break away from his action-hero image.","cn":"史泰龙想要摆脱动作明星的形象。"}},{"pos":"VERB 动词","cn":"处理","en":"If you action something that needs to be done, you deal with it.","ex":{"en":"Documents can be actioned, or filed immediately.","cn":"文件可被立即处理或归档。"}},{"pos":"PHRASE 短语","cn":"（因受伤或损坏）不能工作，失去作用，无法运转","en":"If someone or something is out of action, they are injured or damaged and cannot work or be used.","ex":{"en":"He's been out of action for 16 months with a serious knee injury","cn":"由于膝部严重受伤，他已停工16个月。"}},{"pos":"PHRASE 短语","cn":"（通常为了赚钱或提高影响力）插手，参与","en":"If someone wants to have a piece of the action or a slice of the action, they want to take part in an exciting activity or situation, usually in order to make money or become more important.","ex":{"en":"Holiday spots have seen a dramatic revival and tourist chiefs are competing for a slice of the action.","cn":"各个度假点重又呈现出一派兴旺景象，旅游业的龙头老大们都在争着分一杯羹。"}},{"pos":"PHRASE 短语","cn":"把…付诸实践","en":"If you put an idea or policy into action, you begin to use it or cause it to operate.","ex":{"en":"They have learned the lessons of business management theory, and put them into action.","cn":"他们不仅学习了商业管理理论方面的课程，并且学以致用。"}}]},"examples":[{"en":"The time has come for action if these beautiful animals are to survive.","cn":"若要使这些美丽的动物能生存下去，现在就要行动起来。"},{"en":"Foreign firms will all want a piece of the action if the new airport goes ahead.","cn":"要是新机场开始修建，外国公司都会来插一手捞好处。"}]},"activate":{"oxford":{"phon":"ˈæktɪveɪt","pos":"verb","senses":[{"en":"to make something such as a device or chemical process start working","cn":"使活动；激活；使活化","ex":{"en":"The burglar alarm is activated by movement.","cn":"这防盗警报器一动就会响。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"使运作；使起作用；激活","en":"If a device or process is activated, something causes it to start working.","ex":{"en":"Video cameras with night vision can be activated by movement.","cn":"带夜视镜的摄像机一有动静就会启动。"}}]},"media":{"uk":"media/uk/activate__gb_1.mp3","us":"media/us/activate__us_1.mp3"},"examples":[{"en":"The gene is activated by a specific protein.","cn":"这种基因由一种特异性蛋白激活。"},{"en":"The burglar alarm is activated by movement.","cn":"这防盗警报器一动就会响。"}]},"accomplished":{"media":{"uk":"media/uk/accomplished__gb_1.mp3","us":"media/us/accomplished__us_1.mp3"},"oxford":{"phon":"əˈkʌmplɪʃt","pos":"adjective","senses":[{"en":"very good at a particular thing; having a lot of skills","cn":"才华高的；技艺高超的；熟练的","ex":{"en":"an accomplished artist/actor/chef","cn":"技艺高超的艺术家／演员／厨师"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"熟练的;才华高的;有造诣的","en":"If someone is accomplished at something, they are very good at it.","ex":{"en":"She is an accomplished painter.","cn":"她是位颇有建树的画家。"}}]},"examples":[{"en":"She was an elegant and accomplished woman.","cn":"她是位优雅的才女。"},{"en":"an accomplished artist/actor/chef","cn":"技艺高超的艺术家/演员/厨师"}]},"acutely":{"oxford":{"phon":"əˈkjuːtli","pos":"adverb","senses":[{"en":"noticing or feeling something very strongly","cn":"深深感觉到；强烈意识到","ex":{"en":"I am acutely aware of the difficulties we face.","cn":"我十分清楚我们面临的困难。"}},{"en":"(describing unpleasant feelings) very; very strongly","cn":"（描述不快的感觉）极其，强烈地","ex":{"en":"acutely embarrassed","cn":"极其尴尬"}},{"en":"to a severe and dangerous degree","cn":"严重地；危险地","ex":{"en":"acutely ill","cn":"病重"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"深深地（感觉到），强烈地(意识到)","en":"If you feel or notice something acutely, you feel or notice it very strongly.","ex":{"en":"He was acutely aware of the odour of cooking oil","cn":"他闻到一股浓浓的油烟味。"}},{"pos":"ADV-GRADED 副词","cn":"（感觉、性质）极其","en":"If a feeling or quality is acutely unpleasant, it is extremely unpleasant.","ex":{"en":"It was an acutely uncomfortable journey back to London.","cn":"那是一次极其痛苦的返回伦敦的旅行。"}}]},"media":{"uk":"media/uk/acutely__gb_1.mp3","us":"media/us/acutely__us_1.mp3"},"examples":[{"en":"I am acutely aware of the difficulties we face.","cn":"我十分清楚我们面临的困难。"},{"en":"acutely embarrassed","cn":"极其尴尬"}]},"actress":{"oxford":{"phon":"ˈæktrəs","pos":"noun","senses":[{"en":"a woman who performs on the stage, on television or in films, especially as a profession","cn":"女演员","lab":"British English","ex":{"en":"The Oscar-winning actress has taken a break from acting.","cn":"这位奥斯卡获奖女演员已经暂别演艺圈。"}},{"en":"a woman who plays a part, pretending by her behaviour to be a particular kind of person","cn":"（某种角色的）女扮演者","ex":{"en":"I became a very good actress and they nearly always believed me.","cn":"我装得很好，他们几乎总是相信我。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"女演员","en":"An actress is a woman whose job is acting in plays or films.","ex":{"en":"She's a very great dramatic actress.","cn":"她是一个非常了不起的戏剧演员。"}}]},"media":{"uk":"media/uk/actress__gb_1.mp3","us":"media/us/actress__us_1.mp3"}},"achieve":{"media":{"uk":"media/uk/achieve__gb_1.mp3","us":"media/us/achieve__us_1.mp3"},"oxford":{"phon":"əˈtʃiːv","pos":"verb","senses":[{"en":"to succeed in reaching a particular goal, status or standard, especially by making an effort for a long time","cn":"（凭长期努力）达到（某目标、地位、标准）","g":"[transitive]","ex":{"en":"He had finally achieved success.","cn":"他终于获得了成功。"}},{"en":"to succeed in doing something or causing something to happen","cn":"完成","g":"[transitive]","ex":{"en":"I haven't achieved very much today.","cn":"我今天没做成多少事。"}},{"en":"to be successful","cn":"成功","g":"[intransitive]","ex":{"en":"Their background gives them little chance of achieving at school.","cn":"他们的家庭背景使他们很难在学校获得成功。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（经努力）完成，达到，获得","en":"If you achieve a particular aim or effect, you succeed in doing it or causing it to happen, usually after a lot of effort.","ex":{"en":"There are many who will work hard to achieve these goals","cn":"有志之士将会共同为实现这些目标而努力。"}}]},"examples":[{"en":"Their background gives them little chance of achieving at school.","cn":"他们的家庭背景使他们很难有机会在学校学有所成。"},{"en":"They could not achieve their target of less than 3% inflation.","cn":"他们未能达到通货膨胀低于 3% 的目标。"}]},"activating":{"oxford":{"phon":"ˈæktɪveɪt","pos":"verb","senses":[{"en":"to make sth such as a device or chemical process start working","cn":"使活动；激活；使活化"}]}},"accuracies":{"oxford":{"phon":"ˈækjərəsi","pos":"noun","senses":[{"en":"the state of being exact or correct; the ability to do sth skilfully without making mistakes","cn":"准确（性）；精确（程度）"}]}},"accused":{"oxford":{"phon":"əˈkjuːzd","pos":"noun","senses":[{"en":"a person who is on trial for committing a crime （","cn":"刑事）被告"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"被告","en":"You can use the accused to refer to a person or a group of people charged with a crime or on trial for it.","ex":{"en":"The accused is alleged to be a member of a right-wing gang","cn":"据称被告是某右翼组织的成员。"}}]},"media":{"uk":"media/uk/accused__gb_1.mp3","us":"media/us/accused__us_1.mp3"},"examples":[{"en":"All the accused have pleaded guilty.","cn":"所有被告都表示服罪。"},{"en":"The accused was found innocent.","cn":"被告被判定无罪。"}]},"accompanied":{"oxford":{"phon":"əˈkʌmpəni","pos":"verb","senses":[{"en":"( formal ) to travel or go somewhere with sb","cn":"陪同；陪伴"},{"en":"to happen or appear with sth else","cn":"伴随；与 … 同时发生"}]}},"actors":{"oxford":{"phon":"ˈæktə(r)","pos":"noun","senses":[{"en":"a person who performs on the stage, on television or in films/movies, especially as a profession","cn":"演员"}]}},"accounts":{"oxford":{"phon":"əˈkaʊnt","pos":"noun","senses":[{"en":"an arrangement that sb has with a bank, etc. to keep money there, take some out, etc.","cn":"账户"},{"en":"a written record of money that is owed to a business and of money that has been paid by it","cn":"账目"}]}},"accounted":{"oxford":{"phon":"əˈkaʊnt","pos":"noun","senses":[{"en":"an arrangement that sb has with a bank, etc. to keep money there, take some out, etc.","cn":"账户"},{"en":"a written record of money that is owed to a business and of money that has been paid by it","cn":"账目"}]}},"accepts":{"oxford":{"phon":"əkˈsept","pos":"verb","senses":[{"en":"to take willingly sth that is offered; to say ‘yes’ to an offer, invitation, etc.","cn":"收受；接受（建议、邀请等）"},{"en":"to receive sth as suitable or good enough （","cn":"认为合适或足够好而）接受"}]}},"acted":{"oxford":{"phon":"ækt","pos":"noun","senses":[{"en":"a particular thing that sb does","cn":"行为；行动；所为"},{"en":"a law that has been passed by a parliament （","cn":"议会通过的）法案，法令"}]}},"acquired":{"oxford":{"phon":"əˈkwaɪə(r)","pos":"verb","senses":[{"en":"to gain sth by your own efforts, ability or behaviour （","cn":"通过努力、能力、行为表现）获得，得到"},{"en":"to obtain sth by buying or being given it","cn":"购得；获得；得到"}]}},"activities":{"oxford":{"phon":"ækˈtɪvəti","pos":"noun","senses":[{"en":"a situation in which sth is happening or a lot of things are being done","cn":"活动；热闹状况；活跃"},{"en":"a thing that you do for interest or pleasure, or in order to achieve a particular aim （","cn":"为兴趣、娱乐或达到一定目的而进行的）活动"}]}},"according":{"oxford":{"phon":"əˈkɔːd","pos":"noun","senses":[{"en":"a formal agreement between two organizations, countries, etc.","cn":"协议；条约"},{"en":"( formal ) in agreement with","cn":"与 … 一致（或相符合）"}]}},"acres":{"oxford":{"phon":"ˈeɪkə(r)","pos":"noun","senses":[{"en":"a unit for measuring an area of land; 4 840 square yards or about 4 050 square metres","cn":"英亩（4 840 平方码，约为 4 050 平方米）"}]}},"achieved":{"oxford":{"phon":"əˈtʃiːv","pos":"verb","senses":[{"en":"to succeed in reaching a particular goal, status or standard, especially by making an effort for a long time （","cn":"凭长期努力）达到（某目标、地位、标准）"},{"en":"to succeed in doing sth or causing sth to happen","cn":"完成"}]}},"acts":{"oxford":{"phon":"ækt","pos":"noun","senses":[{"en":"a particular thing that sb does","cn":"行为；行动；所为"},{"en":"a law that has been passed by a parliament （","cn":"议会通过的）法案，法令"}]}},"acquiring":{"oxford":{"phon":"əˈkwaɪə(r)","pos":"verb","senses":[{"en":"to gain sth by your own efforts, ability or behaviour （","cn":"通过努力、能力、行为表现）获得，得到"},{"en":"to obtain sth by buying or being given it","cn":"购得；获得；得到"}]}},"accountants":{"oxford":{"phon":"əˈkaʊntənt","pos":"noun","senses":[{"en":"a person whose job is to keep or check financial accounts","cn":"会计；会计师"}]}},"actions":{"oxford":{"phon":"ˈækʃn","pos":"noun","senses":[{"en":"the process of doing sth in order to make sth happen or to deal with a situation","cn":"行动；行为过程"},{"en":"a thing that sb does","cn":"所做之事；行为"}]}},"accepted":{"oxford":{"phon":"əkˈseptɪd","pos":"adjective","senses":[{"en":"generally believed to be correct","cn":"公认的；广泛认可的","ex":{"en":"What if the accepted wisdom is wrong?","cn":"要是普遍接受的看法错了怎么办？"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"为公众所接受的；公认的","en":"Accepted ideas are agreed by most people to be correct or reasonable.","ex":{"en":"There is no generally accepted definition of life","cn":"关于生活的定义不一而足。"}}]},"media":{"uk":"media/ldoce/hwd/bre/d/brelasdeaccepted.mp3","us":"media/ldoce/hwd/ame/9/laadaccepted.mp3"},"examples":[{"en":"Having more than one wife is a normal and accepted practice in some countries.","cn":"在一些国家﹐一夫多妻是正常的﹑被认可的做法。"},{"en":"generally accepted principles of fairness and justice","cn":"人们普遍接受的关于公平﹑公正的观念"}]},"acupuncture":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"针刺；针刺疗法","en":"Acupuncture is the treatment of a person's illness or pain by sticking small needles into their body at certain places.","ex":{"en":"All of those who received the true acupuncture experienced pain relief.","cn":"所有接受了针刺治疗的人都感到疼痛减轻了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a treatment for pain and disease that involves pushing special needles into parts of the body","cn":"针刺（疗法）"}]},"collocations":{"phrases":["QUANT. course My doctor recommended a course of acupuncture.","VERB + ACUPUNCTURE have I'm having acupuncture for a bad back. | give sb, practise, use Acupuncture has been practised in China for thousand","ACUPUNCTURE + NOUN point Needles are inserted into specific acupuncture points in the body. | needle"]},"media":{"uk":"media/ldoce/hwd/bre/5/acupuncture0205.mp3","us":"media/ldoce/hwd/ame/f/acupuncture.mp3"},"examples":[{"en":"the four main acupuncture points","cn":"四大穴位"}],"oxford":{"phon":"ˈækjupʌŋktʃə(r)","pos":"noun","senses":[{"en":"a method of treating pain and illness using special thin needles that are pushed into the skin in particular parts of the body","cn":"针刺疗法","ex":{"en":"I'm having acupuncture for a bad back.","cn":"我正在接受针刺治疗背痛。"}}]}},"accelerate":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）加快；（使）增速","en":"If the process or rate of something accelerates or if something accelerates it, it gets faster and faster.","ex":{"en":"Growth will accelerate to 2.9 per cent next year","cn":"明年的增长会加快到2.9%。"}},{"pos":"VERB 动词","cn":"（运动中的车辆）加速","en":"When a moving vehicle accelerates, it goes faster and faster.","ex":{"en":"Suddenly the car accelerated","cn":"汽车突然加速。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make something happen more quickly","cn":""},{"en":"if a vehicle, especially a large vehicle picks up speed or gathers speed , it starts to gradually move faster","cn":""},{"en":"if a vehicle or driver accelerates , they go faster, especially suddenly","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Accelerate means to speed up. A car accelerates when you step on the gas. You can accelerate the process of getting a visa if you happen to know someone who works in the consulate."}]},"collocations":{"phrases":["ADV. hard, quickly | smoothly The runners accelerated smoothly round the bend. | suddenly | away The car purred into life and accelerated aw","ADV. dramatically, greatly, rapidly, sharply The Aids epidemic is accelerating dramatically."]},"media":{"uk":"media/ldoce/hwd/bre/6/accelerate0205.mp3","us":"media/ldoce/hwd/ame/0/accelerate.mp3"},"examples":[{"en":"Exposure to the sun can accelerate the ageing process.","cn":"暴露在日光下会加快老化过程。"},{"en":"The runners accelerated smoothly around the bend.","cn":"赛跑运动员在转弯处顺势加速。"}],"oxford":{"phon":"əkˈseləreɪt","pos":"verb","senses":[{"en":"to happen faster or earlier; to make something happen faster or earlier","cn":"（使）加速，加快","g":"[intransitive, transitive]","ex":{"en":"Inflation continues to accelerate.","cn":"通货膨胀不断加速。"}},{"en":"to start to go faster","cn":"加速；加快","g":"[intransitive]","ex":{"en":"The runners accelerated smoothly around the bend.","cn":"赛跑运动员在转弯处顺势加速。"}}]}},"accolade":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"赞扬；荣誉；奖励","en":"If someone is given an accolade, something is done or said about them which shows how much people admire them.","ex":{"en":"The Nobel prize has become the ultimate accolade in the sciences","cn":"诺贝尔奖已成为科学界的最高荣誉。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"praise for someone who is greatly admired, or a prize given to them for their work","cn":"赞扬﹔嘉奖﹐奖励"},{"en":"ultimate/highest/supreme etc accolade She received a Grammy Award, the highest accolade in the music business.","cn":"她获得了音乐界的最高奖项——格莱美奖。"}]},"vocab":{"pos":"n","senses":[{"en":"A knight being honored with the tap of a sword-blade was the earliest form of accolade . Today, an accolade is more than a way to bestow knighthood, it is a form of praise or an award."}]},"collocations":{"phrases":["ADJ. greatest, highest, supreme, ultimate Four restaurants have been awarded the highest accolade of a three-star rating.","VERB + ACCOLADE earn, receive, win | award (sb), bestow, grant (sb) | deserve"]},"media":{"uk":"media/ldoce/hwd/bre/6/accolade0205.mp3","us":"media/ldoce/hwd/ame/d/accolade.mp3"},"oxford":{"phon":"ˈækəleɪd","pos":"noun","senses":[{"en":"praise or an award for an achievement that people admire","cn":"赞扬；表扬；奖励；荣誉","ex":{"en":"Four restaurants have been awarded the highest accolade of a three-star rating.","cn":"4 家餐馆被授予三星级餐馆的最高荣誉称号。"}}]}},"accountant":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"会计员；会计师","en":"An accountant is a person whose job is to keep financial accounts."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone whose job is to keep and check financial accounts, calculate taxes etc","cn":"会计师﹔会计"}]},"collocations":{"phrases":["ADJ. certified, chartered | professional, qualified | trainee | retired | independent, self-employed | company | chief We talked to the comp"]},"media":{"uk":"media/ldoce/hwd/bre/4/accountant0205.mp3","us":"media/ldoce/hwd/ame/b/accountant.mp3"},"oxford":{"phon":"əˈkaʊntənt","pos":"noun","senses":[{"en":"a person whose job is to keep or check financial accounts","cn":"会计；会计师","ex":{"en":"We talked to the company’s chief accountant.","cn":"我们和公司的总会计师进行了交谈。"}}]}},"ace":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"A纸牌","en":"An ace is a playing card with a single symbol on it. In most card games, the ace of a particular suit has either the highest or the lowest value of the cards in that suit.","ex":{"en":"...the ace of hearts.","cn":"红桃A"}},{"pos":"N-COUNT 可数名词","cn":"（在运动等方面）成绩超群的人，佼佼者","en":"If you describe someone such as a sports player as an ace, you mean that they are very good at what they do.","ex":{"en":"...former motor-racing ace Stirling Moss.","cn":"前一流赛车手斯特林·莫斯"}},{"pos":"ADJ 形容词","cn":"非常好的；顶呱呱的","en":"If you say that something is ace, you think that it is good and you like it a lot.","ex":{"en":"...a really ace film.","cn":"精彩绝伦的电影"}},{"pos":"N-COUNT 可数名词","cn":"（网球中的）发球得分，爱司球","en":"In tennis, an ace is a serve which is so fast that the other player cannot reach the ball.","ex":{"en":"The American served three aces in the opening game of the set.","cn":"这位美国选手在该盘首局有三次发球直得。"}},{"pos":"PHRASE 短语","cn":"占绝对优势；占尽天时地利人和","en":"If you say that someone holds all the aces, you mean that they have all the advantages in a contest or situation.","ex":{"en":"'When I was an adolescent,' says a thirty-one-year-old man, 'I thought girls held all the aces.'","cn":"“当我还是个毛头小伙儿时，”一个31岁的男人说，“我觉得完全是女孩子说了算。”"}},{"pos":"PHRASE 短语","cn":"秘藏的王牌;应急的绝招;锦囊妙计","en":"Something that is an ace in the hole is an advantage which you have over an opponent or rival, and which you can use if necessary.","ex":{"en":"Our superior technology is our ace in the hole.","cn":"我们超众的技术是我们的法宝。"}},{"pos":"PHRASE 短语","cn":"差点;险些","en":"If you come within an ace of doing something, or you are within an ace of doing something, you very nearly do or experience it.","ex":{"en":"He was intent on murder and he came within an ace of succeeding.","cn":"他一心想杀人并且差点就得逞了。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a playing card with a single spot on it, which usually has the highest value in a game A","cn":"牌"},{"en":"someone who is extremely skilful at doing something","cn":"一流高手﹐能手"},{"en":"a first shot in tennis or volleyball which is hit so well that your opponent cannot reach the ball and you win the point 〔","cn":"网球或排球的〕发球直接得分﹐ace球"}]},"collocations":{"phrases":["VERB + ACE serve Rafter has served fifteen aces in the match so far. 3 person who is very good at sth","ADJ. fighter, flying, goal, motorcycle, soccer, tennis"]},"media":{"uk":"media/ldoce/hwd/bre/8/ace_n0205.mp3","us":"media/ldoce/hwd/ame/c/ace1.mp3"},"examples":[{"en":"He served 20 aces in the match.","cn":"他在这场比赛中发了 20 个爱司球。"},{"en":"We came within an ace of victory.","cn":"我们差一点儿就要胜利了。"}],"oxford":{"phon":"eɪs","pos":"noun","senses":[{"en":"a playing card with a large single symbol on it, which has either the highest or the lowest value in a particular card game","cn":"A 纸牌（亦称“爱司”）","ex":{"en":"the ace of spades/hearts/diamonds/clubs","cn":"黑桃／红心／方块／梅花 A"}},{"en":"a person who is very good at doing something","cn":"擅长…的人；精于…的人","lab":"informal","ex":{"en":"a soccer/flying ace","cn":"足球／飞行顶尖高手"}},{"en":"a serve (= the first hit) that is so good that your opponent cannot reach the ball","cn":"爱司球（对手未碰到的优质发球）","ex":{"en":"He served 20 aces in the match.","cn":"他在这场比赛中发了 20 个爱司球。"}},{"en":"an occasion when a player hits the ball from the tee into the hole using only one shot","cn":"一杆进洞"},{"en":"very good","cn":"第一流的；极好的","ex":{"en":"We had an ace time.","cn":"我们过得真痛快。"},"pos":"adjective"},{"en":"to be successful in something","cn":"在…中获得成功","ex":{"en":"He aced all his tests.","cn":"他通过了对他的所有测试。"},"pos":"verb"},{"en":"a US company that makes various types of elastic bandage","cn":"Ace 公司（美国一家生产医用弹性绷带的公司）"}]}},"accustomed":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"习惯的；适应的","en":"If you are accustomed to something, you know it so well or have experienced it so often that it seems natural, unsurprising, or easy to deal with.","ex":{"en":"I was accustomed to being the only child at a table full of adults","cn":"我已经习惯了作为唯一一个小不点坐在一桌大人中间。"}},{"pos":"ADJ 形容词","cn":"（眼睛对光线变化）习惯了的,适应了的","en":"When your eyes become accustomed to darkness or bright light, they adjust so that you start to be able to see things, after not being able to see properly at first.","ex":{"en":"My eyes were becoming accustomed to the gloom.","cn":"我的眼睛渐渐适应了黑暗。"}},{"pos":"ADJ 形容词","cn":"通常的;惯常的","en":"You can use accustomed to describe an action that someone usually does, a quality that they usually show, or an object that they usually use.","ex":{"en":"He took up his accustomed position with his back to the fire","cn":"他背对着炉火在通常的位子上坐了下来。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if you are used to something, you have often done it or experienced it before, so it does not seem strange, new, or difficult to you","cn":""},{"en":"to be used to something, especially because it is a normal part of your life","cn":""},{"en":"to be so used to something that you feel comfortable and happy with it, especially because you have learned how to do it well","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you're accustomed to something, you're used to it. Being accustomed has to do with habits and lifestyle."}]},"collocations":{"phrases":["VERBS be | become, get, grow She had grown accustomed to his long absences.","ADV. quite, well He was well accustomed to hard work."]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdeaccustomed.mp3","us":"media/ldoce/hwd/ame/8/accustomed.mp3"},"examples":[{"en":"She was a person accustomed to having eight hours' sleep a night.","cn":"她是那种习惯每晚睡八个小时的人。"},{"en":"He took his accustomed seat by the fire.","cn":"他坐在炉火边惯常坐的座位。"}],"oxford":{"phon":"əˈkʌstəmd","pos":"adjective","senses":[{"en":"familiar with something and accepting it as normal or usual","cn":"习惯于","lab":"rather formal","ex":{"en":"to become/get accustomed to something","cn":"习惯于某事物"}},{"en":"usual","cn":"通常的；平常的；惯常的","g":"[usually before noun]","lab":"formal","ex":{"en":"He took his accustomed seat by the fire.","cn":"他坐了炉火边惯常坐的座位。"}}]}},"accidental":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"意外的；偶然（发生）的","en":"An accidental event happens by chance or as the result of an accident, and is not deliberately intended.","ex":{"en":"The jury returned a verdict of accidental death","cn":"陪审团作出意外死亡的正式裁决。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"happening without being planned or intended","cn":"偶然的﹐意外的"},{"en":"if you do something by mistake , you intend to do one thing, but you accidentally do something else instead","cn":""},{"en":"if you mistakenly do something, you intend to do one thing, but you accidentally do something else instead, especially because you are confused","cn":""}]},"vocab":{"pos":"1 adj 2 n","senses":[{"en":"Anything accidental happens by chance or unintentionally. People don't mean to do accidental things."}]},"collocations":{"phrases":["VERBS be","ADV. completely, purely, quite | almost"]},"media":{"uk":"media/ldoce/hwd/bre/3/accidental0205.mp3","us":"media/ldoce/hwd/ame/4/accidental.mp3"},"examples":[{"en":"I didn't think our meeting was accidental — he must have known I would be there.","cn":"我认为我们相遇不是偶然的 — 他肯定知道我要去那里。"},{"en":"The damage couldn't have been caused accidentally.","cn":"这次损毁不可能是偶然因素造成的。"}],"oxford":{"phon":"ˌæksɪˈdentl","pos":"adjective","senses":[{"en":"happening by chance; not planned","cn":"意外的；偶然的","ex":{"en":"a verdict of accidental death","cn":"意外死亡的裁决"}}]}},"ache":{"collins":{"senses":[{"pos":"VERB 动词","cn":"（持续并较强烈地）疼痛","en":"If you ache or a part of your body aches, you feel a steady, fairly strong pain.","ex":{"en":"Her head was throbbing and she ached all over","cn":"她的脑袋嗡嗡作响并且浑身疼痛。"}},{"pos":"N-COUNT 可数名词","cn":"（身体某部位持续且较强烈的)疼痛","en":"An ache is a steady, fairly strong pain in a part of your body.","ex":{"en":"You feel nausea and aches in your muscles","cn":"症状为恶心和肌肉疼痛。"}},{"pos":"VERB 动词","cn":"渴望（且因得不到而痛苦）","en":"If you ache for something or your heart aches, you want something very much, and feel very unhappy because you cannot have it.","ex":{"en":"She still ached for the lost intimacy and sexual contact of marriage","cn":"她仍旧渴望拥有婚姻中逝去的那份缱绻和肌肤之亲。"}},{"pos":"PHRASE 短语","cn":"（泛指较轻微的）身体疼痛","en":"You can use aches and pains to refer in a general way to any minor pains that you feel in your body.","ex":{"en":"It seems to ease all the aches and pains of a hectic and tiring day.","cn":"繁忙劳碌了一天所带来的周身酸痛似乎被一扫而空。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if part of your body hurts, it feels painful","cn":""},{"en":"to hurt with a continuous pain","cn":""},{"en":"to feel a bad pain that comes and goes again in a regular and continuous way","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"An ache is a dull, lingering pain. An ache in your calves after your morning jog might mean you didn't stretch enough before you started running."}]},"collocations":{"phrases":["ADV. badly, really My feet ached badly. | a bit My left foot ached a bit.","PREP. from I still really ache from all that cycling yesterday.","PHRASES ache all over Her head felt hot and she was aching all over."]},"media":{"uk":"media/ldoce/hwd/bre/2/ache_v0205.mp3","us":"media/ldoce/hwd/ame/6/ache1.mp3"},"examples":[{"en":"Her eyes ached from lack of sleep.","cn":"她的眼睛因睡眠不足而隐隐作痛。"},{"en":"( figurative ) It makes my heart ache (= it makes me sad) to see her suffer.","cn":"看到她在受苦，我心里真难过。"}],"oxford":{"phon":"eɪk","pos":"verb","senses":[{"en":"to feel a continuous pain that is not severe","cn":"疼痛；隐痛","lab":"figurative","ex":{"en":"I'm aching all over.","cn":"我周身疼痛。"}},{"en":"to have a strong desire for somebody/something or to do something","cn":"渴望","lab":"formal","ex":{"en":"I was aching for home.","cn":"我很想回家。"}},{"en":"a continuous feeling of pain in a part of the body","cn":"（身体某部位的）疼痛","lab":"figurative","ex":{"en":"Mummy, I've got a tummy ache.","cn":"妈妈，我肚子疼。"},"pos":"noun"}]}},"acceleration":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"加快；增速","en":"The acceleration of a process or change is the fact that it is getting faster and faster.","ex":{"en":"He has also called for an acceleration of political reforms.","cn":"他同时呼吁加快政治改革的步伐。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（汽车等的）加速能力，加速幅度","en":"Acceleration is the rate at which a car or other vehicle can increase its speed, often seen in terms of the time that it takes to reach a particular speed.","ex":{"en":"Acceleration to 60 mph takes a mere 5.7 seconds.","cn":"加速到时速60英里只需要5.7秒。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"加速度","en":"Acceleration is the rate at which the speed of an object increases."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a process in which something happens more and more quickly","cn":"加快﹐增速"},{"en":"the rate at which a car or other vehicle can go faster 〔","cn":"车辆的〕加速能力﹐加速性能"},{"en":"the rate at which the speed of an object increases","cn":"加速度"}]},"vocab":{"pos":"n","senses":[{"en":"Acceleration is the act of increasing speed. When you buy a sports car, you want one that has great acceleration, so it can go from zero to 60 miles an hour in no time."}]},"collocations":{"phrases":["ADJ. rapid","PREP. ~ in There has been a rapid acceleration in the growth of industry. 2 ability of a car to accelerate","ADJ. fast, good This model has the best acceleration of any available sports car. | poor, slow"]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41acceleration.mp3","us":"media/ldoce/hwd/ame/6/acceleration.mp3"},"examples":[{"en":"an acceleration in the rate of economic growth","cn":"经济增长加速"},{"en":"a car with good acceleration","cn":"加速性能良好的汽车"}],"oxford":{"phon":"əkˌseləˈreɪʃn","pos":"noun","senses":[{"en":"an increase in how fast something happens","cn":"加速；加快","g":"[uncountable, singular]","ex":{"en":"an acceleration in the rate of economic growth","cn":"经济增长加速"}},{"en":"the rate at which a vehicle increases speed","cn":"（车辆）加速能力，加速的幅度","g":"[uncountable]","ex":{"en":"a car with good acceleration","cn":"加速性能良好的汽车"}},{"en":"the rate at which the velocity (= speed in a particular direction) of an object changes","cn":"加速度","g":"[uncountable]","lab":"physics","ex":{"en":"acceleration caused by gravity","cn":"重力引起的加速度"}}]}},"acknowledgement":{"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"（对事实、局面等的）承认","en":"An acknowledgement is a statement or action which recognizes that something exists or is true.","ex":{"en":"The President's resignation appears to be an acknowledgment that he has lost all hope of keeping the country together","cn":"总统的辞职似乎表明他对维护国家稳定已不抱任何希望。"}},{"pos":"N-PLURAL 复数名词","cn":"（作者的）致谢，鸣谢","en":"The acknowledgements in a book are the section in which the author thanks all the people who have helped him or her."},{"pos":"N-UNCOUNT 不可数名词","cn":"打招呼的表示（如微笑等）","en":"A gesture of acknowledgement, such as a smile, shows someone that you have seen and recognized them.","ex":{"en":"Farling smiled in acknowledgement and gave a bow","cn":"法林微笑示意，又躬身行了个礼。"}},{"pos":"N-VAR 可变名词","cn":"公开致谢","en":"An acknowledgement is a published statement in which you express your gratitude for or appreciation of something.","ex":{"en":"The benefit to the donor was an acknowledgment of the donation in a printed bulletin","cn":"捐赠者被印入捐赠公示榜以示感谢。"}},{"pos":"N-COUNT 可数名词","cn":"（表示已收到信函等的）确认通知，收件复函","en":"An acknowledgement is a letter or message that you receive from someone, telling you that something you have sent to them has arrived.","ex":{"en":"I have received neither an acknowledgment nor a reply.","cn":"我未收到任何复函或答复。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a written answer to a letter, invitation, or advertisement","cn":""},{"en":"a letter that you write back to someone who has asked you for something","cn":""},{"en":"a formal letter or note stating that a letter, parcel etc has been received","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Giving an acknowledgment is a way of giving credit or props. Acknowledgments let you know who contributed or did work on something."}]},"collocations":{"phrases":["ADJ. brief | explicit | tacit | open, public | formal, official | belated | welcome","VERB + ACKNOWLEDGEMENT amount to, be This amounted to an acknowledgement that she had been wrong. | get, receive I wrote to them but never g","PREP. in ~ (of) He raised his hand to her in acknowledgement. | ~ from She is still waiting for some acknowledgement from her fellow academi","PHRASES with due acknowledgement He borrowed from a number of sources, with due acknowledgement."]},"media":{"uk":"media/ldoce/hwd/bre/5/acknowledgemen0205.mp3","us":"media/ldoce/hwd/ame/c/laadacknowledgement.mp3"},"examples":[{"en":"I was sent a free copy in acknowledgement of my contribution.","cn":"我收到一本赠刊，表示对我投稿的谢意。"},{"en":"The flowers were a small acknowledgement of your kindness.","cn":"这些花聊表谢意，感谢你的好心帮助。"}],"oxford":{"phon":"əkˈnɒlɪdʒmənt","pos":"noun","senses":[{"en":"an act of accepting that something exists or is true, or that something is there","cn":"（对事实、现实、存在的）承认","g":"[singular, uncountable]","ex":{"en":"This report is an acknowledgement of the size of the problem.","cn":"这个报告承认了问题的严重性。"}},{"en":"an act or a statement expressing thanks to somebody; something that is given to somebody as thanks","cn":"感谢；谢礼","g":"[countable, uncountable]","ex":{"en":"The flowers were a small acknowledgement of your kindness.","cn":"这些花聊表谢意，感谢你的好心帮助。"}},{"en":"a letter or an email saying that something has been received","cn":"收件复函","g":"[countable]","ex":{"en":"I didn't receive an acknowledgement of my application.","cn":"我的申请没有得到复信告知收悉。"}},{"en":"a statement, especially at the beginning of a book, in which the writer expresses thanks to the people who have helped","cn":"（尤指作者在卷首的）致谢，鸣谢","g":"[countable, usually plural]","ex":{"en":"a page of acknowledgements","cn":"致谢页"}}]}},"acne":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"痤疮；粉刺","en":"If someone has acne, they have a skin condition which causes a lot of spots on their face and neck."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a medical problem which causes a lot of red spots on your face and neck and mainly affects young people","cn":"痤疮﹐粉刺"}]},"vocab":{"pos":"n","senses":[{"en":"Acne is a skin condition that causes pimples or even a red rash to pop up on your face and sometimes your back and shoulders. Teenagers are often affected by acne , which is a real bummer when you’re trying to flirt."}]},"collocations":{"phrases":["ADJ. bad, terrible","VERB + ACNE have, suffer from He had terrible acne when he was younger. | develop, get A lot of teenagers develop acne. | treat Doctors can ","ACNE + VERB clear (up) Acne often clears up with a change in diet."]},"media":{"uk":"media/ldoce/hwd/bre/1/acne0205.mp3","us":"media/ldoce/hwd/ame/3/acne.mp3"},"examples":[{"en":"to suffer from/have acne","cn":"患痤疮；长粉刺"}],"oxford":{"phon":"ˈækni","pos":"noun","senses":[{"en":"a skin condition, common among young people, that produces many pimples (= spots), especially on the face and neck","cn":"痤疮；粉刺","ex":{"en":"to suffer from/have acne","cn":"患痤疮；长粉刺"}}]}},"acquittal":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"宣告无罪；无罪的判决","en":"Acquittal is a formal declaration in a court of law that someone who has been accused of a crime is innocent.","ex":{"en":"...the acquittal of six police officers charged with beating a suspect","cn":"对6名被控殴打嫌犯的警官作出的无罪判决"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an official statement in a court of law that someone is not guilty","cn":"无罪判决﹐宣判无罪"}]},"vocab":{"pos":"n","senses":[{"en":"Acquittal is a legal word that defendants love to hear because it means \"not guilty.\""}]},"collocations":{"phrases":["VERB + ACQUITTAL return The jury returned an acquittal after only seventeen minutes. | direct, order The trial judge had directed an acquitt"]},"media":{"uk":"media/ldoce/hwd/bre/7/acquittal0205.mp3","us":"media/ldoce/hwd/ame/b/acquittal.mp3"},"examples":[{"en":"The case resulted in an acquittal.","cn":"此案件最终作出无罪判决。"},{"en":"The jury voted for acquittal.","cn":"陪审团表决赞成判定无罪。"}],"oxford":{"phon":"əˈkwɪtl","pos":"noun","senses":[{"en":"an official decision in court that a person is not guilty of a crime","cn":"宣告无罪；无罪的判决","lab":"especially North American English","ex":{"en":"The case resulted in an acquittal.","cn":"此案件最终作出无罪判决。"}}]}},"accountable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有责任的；应作解释的","en":"If you are accountable to someone for something that you do, you are responsible for it and must be prepared to justify your actions to that person.","ex":{"en":"Public officials can finally be held accountable for their actions","cn":"终于要对政府官员实行问责了。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"responsible for the effects of your actions and willing to explain or be criticized for them","cn":"负有责任的"}]},"vocab":{"pos":"adj","senses":[{"en":"If you're responsible for your own actions, you are accountable for them. You are accountable for your behavior in school. So even if your friend throws pudding at you at lunch, you don't have the right to fling mystery meat back."}]},"collocations":{"phrases":["VERBS be | become | make sb | hold sb The directors are held accountable by the shareholders.","ADV. fully, properly | directly Senior managers are directly accountable to the Board of Directors. | publicly Local authorities should be p","PREP. for In the end, we are all accountable for our actions. | to Politicians are accountable to Parliament."]},"media":{"uk":"media/ldoce/hwd/bre/8/accountable0205.mp3","us":"media/ldoce/hwd/ame/6/accountable.mp3"},"examples":[{"en":"Someone must be held accountable for the killings.","cn":"必须有人要对这些凶杀事件负责。"},{"en":"Politicians are ultimately accountable to the voters.","cn":"从政者最终是向选民负责。"}],"oxford":{"phon":"əˈkaʊntəbl","pos":"adjective","senses":[{"en":"responsible for your decisions or actions and expected to explain them when you are asked","cn":"（对自己的决定、行为）负有责任，有说明义务","ex":{"en":"The state spends taxpayers’ money and should be held accountable.","cn":"国家花的是纳税人的钱，所以应该承担责任。"}}]}},"accusation":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"指控；控告；指责","en":"If you make an accusation against someone, you criticize them or express the belief that they have done something wrong.","ex":{"en":"Kim rejects accusations that Country music is over-sentimental","cn":"对于乡村音乐过于感伤的指责，金表示反对。"}},{"pos":"N-COUNT 可数名词","cn":"（尚未证实的被控告的）罪名，罪状","en":"An accusation is a statement or claim by a witness or someone in authority that a particular person has committed a crime, although this has not yet been proved.","ex":{"en":"...people who have made public accusations of rape","cn":"公开指控强奸罪名的人们"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a statement saying that you believe someone is guilty of a crime or of doing something bad","cn":""},{"en":"a public statement accusing someone of doing something although it has not been proved","cn":""},{"en":"an official statement by the police accusing someone of a crime and saying that they must go to court, or a statement saying that someone has done something bad, made by anyone","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"When you say someone is guilty of doing something wrong you make an accusation , like your accusation that your brother used your computer without asking first."}]},"collocations":{"phrases":["ADJ. serious | false, groundless, unfounded, unjust, wild | bitter | mutual They sank into mutual accusation and incrimination. | public | v","VERB + ACCUSATION level at, make an accusation frequently levelled at junior doctors | face Their father now faces an accusation of murder. ","ACCUSATION + VERB fly about/around There seem to be a lot of wild accusations flying around.","PREP. amid ~s He fled the country amid accusations of fraud. | ~ against You made a public accusation of misconduct against Nigel.","PHRASES bring an accusation against sb She rejected all the accusations brought against her."]},"media":{"uk":"media/ldoce/hwd/bre/f/accusation0205.mp3","us":"media/ldoce/hwd/ame/b/accusation.mp3"},"examples":[{"en":"He denied the accusation that he had ignored the problems.","cn":"他否认别人说他忽视这些问题的指控。"},{"en":"I don't want to make an accusation until I have some proof.","cn":"我要有一些证据以后才提出控告。"}],"oxford":{"phon":"ˌækjuˈzeɪʃn","pos":"noun","senses":[{"en":"a statement saying that you think a person is guilty of doing something wrong or illegal; the fact of accusing somebody","cn":"控告；起诉；告发；谴责","ex":{"en":"I don't want to make an accusation until I have some proof.","cn":"我要有一些证据以后才提出控告。"}}]}},"accomplice":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"共犯;同谋;帮凶","en":"Someone's accomplice is a person who helps them to commit a crime.","ex":{"en":"The gunman escaped on a motorcycle being ridden by an accomplice.","cn":"持枪歹徒坐上一辆由同伙驾驶的摩托车逃逸。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who is involved in illegal activities or has been proved guilty of a crime. Criminal is used especially about someone who often does things that are illegal","cn":""},{"en":"someone who breaks the law","cn":""},{"en":"a dishonest person, especially one who steals money and who you cannot trust","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"An accomplice is a cooperator or participator, commonly in criminal acts. So you’re an accomplice to the gas station robbery if you distracted the store manager while your partner in crime raided the registers for cash."}]},"collocations":{"phrases":["ADJ. willing | unwilling | unwitting | alleged","PREP. ~ in She became his unwitting accomplice in the robbery. | ~ to an accomplice to murder"]},"media":{"uk":"media/ldoce/hwd/bre/8/accomplice0205.mp3","us":"media/ldoce/hwd/ame/4/accomplice.mp3"},"oxford":{"phon":"əˈkʌmplɪs","pos":"noun","senses":[{"en":"a person who helps another to commit a crime or to do something wrong","cn":"帮凶；共犯；同谋","ex":{"en":"She became his unwitting accomplice in the robbery.","cn":"她稀里糊涂地成了他进行抢劫的帮凶。"}}]}},"accountancy":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"会计学；会计工作","en":"Accountancy is the theory or practice of keeping financial accounts.","ex":{"en":"He's sitting his final exams in accountancy.","cn":"他正参加会计学的期末考试。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the profession or work of keeping or checking financial accounts, calculating taxes etc","cn":"会计行业﹔会计工作"}]},"collocations":{"phrases":["ADJ. chartered | creative It had taken considerable &lsquo;creative accountancy&rsquo; on my part to produce a set of figures that showed us","ACCOUNTANCY + NOUN firm, practice | body the members of the different professional accountancy bodies | profession • Note at SUBJECT (for mo"]},"media":{"uk":"media/ldoce/hwd/bre/1/accountancy0205.mp3","us":"media/ldoce/hwd/ame/e/accountancy.mp3"},"oxford":{"phon":"əˈkaʊntənsi","pos":"noun","senses":[{"en":"the work or profession of an accountant","cn":"会计工作；会计职业","ex":{"en":"She studied accountancy at university.","cn":"她在大学里学会计。"}}]}},"accuse":{"collins":{"senses":[{"pos":"VERB 动词","cn":"指责;责难","en":"If you accuse someone of doing something wrong or dishonest, you say or tell them that you believe that they did it.","ex":{"en":"He was accusing my mum of having an affair with another man","cn":"他指责我妈妈与另一个男人有染。"}},{"pos":"VERB 动词","cn":"指控；控告","en":"If you are accused of a crime, a witness or someone in authority states or claims that you did it, and you may be formally charged with it and put on trial.","ex":{"en":"Her assistant was accused of theft and fraud by the police","cn":"她的助手被警方指控犯有盗窃和欺诈罪。"}},{"pos":"PHRASE 短语","cn":"遭指责;受指控","en":"If someone stands accused of something, they have been accused of it.","ex":{"en":"The candidate stands accused of breaking promises even before he's in office","cn":"该候选人还未上任就遭指责违背诺言。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to say that you believe that someone is guilty of a crime or of doing something bad","cn":"控告，指控﹔指责"},{"en":"to accuse someone of doing something, although this has not been proved 〔","cn":"在未证实的情况下〕断言﹐声称"},{"en":"if the police charge someone, they officially tell that person that they are believed to be guilty of a crime and that they must go to court 〔","cn":"警方〕指控﹐起诉"}]},"vocab":{"pos":"v","senses":[{"en":"If you charge someone with misdeeds or misconduct, you accuse that person. If the last piece of devil's food cake is missing, your sister may accuse you of eating it — especially if you have chocolate on your mouth."}]},"collocations":{"phrases":["ADV. practically, virtually She practically accused me of starting the fire! | falsely, unjustly, wrongly | angrily | openly, publicly They ","VERB + ACCUSE cannot/could not You can't accuse me of being selfish.","PREP. of No one could ever accuse this government of not caring about the poor.","PHRASES stand accused of He stands accused of murdering his wife and children."]},"media":{"uk":"media/ldoce/hwd/bre/a/accuse0205.mp3","us":"media/ldoce/hwd/ame/f/accuse.mp3"},"examples":[{"en":"( formal ) They stand accused of crimes against humanity.","cn":"他们被控违反人道罪。"},{"en":"The government was accused of incompetence.","cn":"政府被指责无能。"}],"oxford":{"phon":"əˈkjuːz","pos":"verb","senses":[{"en":"to say that somebody has done something wrong or is guilty of something","cn":"控告；控诉；谴责","lab":"formal","ex":{"en":"to accuse somebody of murder/a crime","cn":"控告某人谋杀／犯罪"}}]}},"accelerator":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（汽车等的）加速装置，油门","en":"The accelerator in a car or other vehicle is the pedal which you press with your foot in order to make the vehicle go faster.","ex":{"en":"He eased his foot off the accelerator.","cn":"他松开了油门。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the part of a car or other vehicle that you press with your foot to make it go faster 〔","cn":"车辆的〕加速装置﹐油门"},{"en":"a large machine used to make extremely small pieces of matter 1 (3) move at extremely high speeds （","cn":"粒子）加速器"}]},"vocab":{"pos":"1 n 2 n 3 n","senses":[{"en":"An accelerator makes things go, or accelerate. The gas pedal on a car is an accelerator , but so is a machine that scientists use to speed particles up and smash them."}]},"collocations":{"phrases":["VERB + ACCELERATOR depress, hit, press, put your foot (down) on, step on She put her foot on the accelerator and we sped through the traffic","ACCELERATOR + NOUN pedal"]},"media":{"uk":"media/ldoce/hwd/bre/8/accelerator0205.mp3","us":"media/ldoce/hwd/ame/e/accelerator.mp3"},"oxford":{"phon":"əkˈseləreɪtə(r)","pos":"noun","senses":[{"en":"the pedal in a car or other vehicle that you press with your foot to control the speed of the engine","cn":"（汽车等的）加速装置，油门","lab":"British English","ex":{"en":"She put her foot on the accelerator and we sped through the traffic lights.","cn":"她一踩油门，我们就冲过了红绿灯。"}},{"en":"a machine for making elementary particles move at high speeds","cn":"（基本粒子）加速器","lab":"physics"}]}},"accomplish":{"collins":{"senses":[{"pos":"VERB 动词","cn":"完成；达成","en":"If you accomplish something, you succeed in doing it.","ex":{"en":"If we'd all work together, I think we could accomplish our goal","cn":"只要大家齐心协力，我想我们就能实现目标。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to do something you tried or wanted to do","cn":""},{"en":"to succeed in doing something difficult, after trying hard. Manage to do something is very commonly used instead of succeed in doing something in everyday English","cn":""},{"en":"to succeed in doing something good or important","cn":""}]},"vocab":{"pos":"1 v 2 v","senses":[{"en":"To accomplish something is to get it done. People usually accomplish things that are sources of pride — like goals or records. But people accomplish immoral acts as well — like scandals or cons."}]},"collocations":{"phrases":["ADV. safely, successfully A rather difficult task had been successfully accomplished. | easily"]},"media":{"uk":"media/ldoce/hwd/bre/5/accomplish0205.mp3","us":"media/ldoce/hwd/ame/e/accomplish.mp3"},"examples":[{"en":"The first part of the plan has been safely accomplished.","cn":"计划的第一部分已顺利完成。"},{"en":"I don't feel I've accomplished very much today.","cn":"我觉得我今天没干成多少事。"}],"oxford":{"phon":"əˈkʌmplɪʃ","pos":"verb","senses":[{"en":"to succeed in doing or completing something","cn":"完成","ex":{"en":"The first part of the plan has been safely accomplished.","cn":"计划的第一部分已顺利完成。"}}]}},"accessory":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"附件;配件;附属物","en":"Accessories are items of equipment that are not usually essential, but which can be used with or added to something else in order to make it more efficient, useful, or decorative.","ex":{"en":"...an exclusive range of hand-made bedroom and bathroom accessories.","cn":"独家经营的一系列手工卧室和浴室配件"}},{"pos":"N-COUNT 可数名词","cn":"（衣服的）配饰（如腰带、围巾等）","en":"Accessories are articles such as belts and scarves which you wear or carry but which are not part of your main clothing."},{"pos":"N-COUNT 可数名词","cn":"同谋；帮凶；从犯","en":"If someone is guilty of being an accessory to a crime, they helped the person who committed it, or knew it was being committed but did not tell the police.","ex":{"en":"She was charged with being an accessory to the embezzlement of funds.","cn":"她被指控为这起挪用公款案的从犯。"}},{"pos":"ADJ 形容词","cn":"附属的；辅助的；非主要的","en":"You can use accessory to describe something which is part of an activity or process, but not the most essential or important part of it.","ex":{"en":"Forster established the essentiality of minerals as accessory food factors required for maintaining life.","cn":"福斯特证实了矿物质作为辅助食物因子在维持生命方面的重要性。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something such as a piece of equipment or a decoration that is not necessary, but that makes a machine, car, room etc more useful or more attractive","cn":"附件﹐配件﹐附属品"},{"en":"something such as a bag, belt, or jewellery that you wear or carry because it is attractive","cn":"装饰物﹐小配件〔如手袋﹑皮带﹑珠宝等〕"},{"en":"someone who helps a criminal, especially by helping them hide from the police","cn":"同谋﹐帮凶﹐〔尤指帮助藏匿的〕从犯"}]},"vocab":{"pos":"1 n 2 n adj","senses":[{"en":"Whether we're talking about a fog light for your boat or just a nice hat to go with your boating outfit, an accessory is something you add to something else to make it better."}]},"collocations":{"phrases":["ADJ. essential, perfect, useful This silk scarf is the perfect accessory for stylish summer evenings. | bathroom, car, fashion 2 person who ","PREP. ~ to an accessory to murder","PHRASES an accessory before/after the fact (= a person who knows about a crime before/after it was committed and protects the criminal) (law"]},"media":{"uk":"media/ldoce/hwd/bre/e/accessory0205.mp3","us":"media/ldoce/hwd/ame/d/accessory.mp3"},"examples":[{"en":"a range of furnishings and accessories for the home","cn":"各种各样的家居装饰物及配件"},{"en":"He was charged with being an accessory to murder.","cn":"他被控为谋杀罪的从犯。"}],"oxford":{"phon":"əkˈsesəri","pos":"noun","senses":[{"en":"an extra piece of equipment that is useful but not essential or that can be added to something else as a decoration","cn":"附件；配件；附属物","g":"[usually plural]","ex":{"en":"We stock a large range of bicycle accessories.","cn":"我们库存了各类自行车配件。"}},{"en":"a thing that you can wear or carry that matches your clothes, for example a belt or a bag","cn":"（衣服的）配饰","g":"[usually plural]","ex":{"en":"fashion accessories to dress up your wardrobe","cn":"装扮衣橱的时尚配饰"}},{"en":"a person who helps somebody to commit a crime or who knows about it and protects the person from the police","cn":"同谋；从犯；帮凶","lab":"law","ex":{"en":"He was charged with being an accessory to murder.","cn":"他被控为谋杀罪的从犯。"}},{"en":"not the most important when compared to others","cn":"辅助的；副的","ex":{"en":"the accessory muscles of respiration","cn":"辅助呼吸肌"},"pos":"adjective"}]}},"acclaim":{"collins":{"senses":[{"pos":"VERB 动词","cn":"称赞;赞扬","en":"If someone or something is acclaimed, they are praised enthusiastically.","ex":{"en":"She has been acclaimed for the TV drama 'Prime Suspect'","cn":"她凭借电视剧《头号嫌疑犯》而受到好评。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"公开赞扬;称誉","en":"Acclaim is public praise for someone or something.","ex":{"en":"Angela Bassett has won critical acclaim for her excellent performance","cn":"安吉拉·贝塞特凭借其出色的表演赢得了评论界的好评。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to praise someone or something publicly","cn":"公开称赞﹔推崇"},{"en":"praise for a person or their achievements","cn":"表扬﹐赞赏"}]},"vocab":{"pos":"n v","senses":[{"en":"You know you've hit it big, when you earn acclaim , or enthusiastic approval. And when you have achieved \"critical acclaim ,\" even the grouchy critics approve of you."}]},"collocations":{"phrases":["ADJ. great | general, public, universal, wide, widespread | popular | critical Her latest novel has won great critical acclaim. | internatio","VERB + ACCLAIM earn (sb), gain (sb), meet with, receive, win His discoveries earned him wide acclaim.","PREP. to &hellip; ~ The play opened last week to universal acclaim. | ~ for She received international acclaim for her interpretation of Cho"]},"media":{"uk":"media/ldoce/hwd/bre/c/acclaim_n0205.mp3","us":"media/ldoce/hwd/ame/d/acclaim1.mp3"},"examples":[{"en":"The work was acclaimed as a masterpiece.","cn":"该作品被誉为杰作。"},{"en":"international/popular/critical acclaim","cn":"国际上的/公众的/评论家的赞扬"}],"oxford":{"phon":"əˈkleɪm","pos":"verb","senses":[{"en":"to praise or welcome somebody/something publicly","cn":"公开称誉某人／某事物（为…）；给予高度评价","ex":{"en":"The work was acclaimed as a masterpiece.","cn":"该作品被誉为杰作。"}},{"en":"praise and approval for somebody/something, especially an artistic achievement","cn":"（尤指对艺术成就的）称誉，高度评价","ex":{"en":"international/popular/critical acclaim","cn":"国际上的／公众的／评论家的赞扬"},"pos":"noun"}]}},"accompaniment":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"伴奏","en":"The accompaniment to a song or tune is the music that is played at the same time as it and forms a background to it.","ex":{"en":"He sang 'My Funny Valentine' to a piano accompaniment.","cn":"他在钢琴的伴奏下演唱了《我可爱的情人》。"}},{"pos":"N-COUNT 可数名词","cn":"伴随物；伴随发生（或存在）的事物","en":"An accompaniment is something which goes with another thing.","ex":{"en":"This recipe makes a good accompaniment to ice-cream.","cn":"这道食谱适合搭配冰激凌。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"music that is played in the background at the same time as another instrument or singer that plays or sings the main tune","cn":"伴奏；伴唱"},{"en":"something that is provided or used with something else","cn":"搭配物﹔配料"},{"en":"while something else is happening or while another sound can be heard","cn":"在…的伴随下"}]},"vocab":{"pos":"n","senses":[{"en":"If your menu tonight consists of grilled pork and savory apples, then the pork is the main item and the apples are the accompaniment , meaning they complement the main dish."}]},"collocations":{"phrases":["ADJ. delicious, good, ideal","VERB + ACCOMPANIMENT be, make","PREP. ~ for/to These wines also make a good accompaniment for vegetarian dishes. 2 music played to go with singing, etc.","ADJ. instrumental, musical, orchestral | piano, string, etc.","VERB + ACCOMPANIMENT provide | compose, write","PREP. to the ~ of She sang to the accompaniment of guitars. | with an ~ I prefer to sing with an accompaniment. 3 sth that happens at the sa","ADJ. essential, inevitable, necessary","PREP. to the ~ of The women's medical school opened in 1874, to the accompaniment of much ridicule of &lsquo;lady doctors&rsquo;. | with the"]},"media":{"uk":"media/ldoce/hwd/bre/7/accompaniment0205.mp3","us":"media/ldoce/hwd/ame/0/accompaniment.mp3"},"examples":[{"en":"The wine makes a good accompaniment to fish dishes.","cn":"这种葡萄酒很适合作鱼菜的佐餐酒。"},{"en":"She made her speech to the accompaniment of loud laughter.","cn":"她的演讲不断引起哄堂大笑。"}],"oxford":{"phon":"əˈkʌmpənimənt","pos":"noun","senses":[{"en":"music that is played to support singing or another instrument","cn":"（音乐）伴奏","g":"[countable, uncountable]","ex":{"en":"traditional songs with piano accompaniment","cn":"用钢琴伴奏的传统歌曲"}},{"en":"something that you eat, drink or use together with something else","cn":"佐餐物；伴随物","g":"[countable]","ex":{"en":"The wine makes a good accompaniment to fish dishes.","cn":"这种葡萄酒很适合作鱼菜的佐餐酒。"}},{"en":"something that happens or exists at the same time as another thing","cn":"伴随发生的事情；伴生物","g":"[countable]","lab":"formal","ex":{"en":"The sun was back, with its accompaniment of dust and flies.","cn":"太阳重新露了出来，灰尘和苍蝇也随之出现。"}}]}},"acumen":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"敏锐;聪明","en":"Acumen is the ability to make good judgments and quick decisions.","ex":{"en":"His sharp business acumen meant he quickly rose to the top.","cn":"他精明的商业头脑令其青云直上。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the ability to think quickly and make good judgments","cn":"敏锐﹐聪明﹐机智"},{"en":"business/political/financial etc acumen The firm’s success is largely due to Brannon’s commercial acumen.","cn":"该公司的成功主要归功于布兰农的商业头脑。"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"If you have acumen , you are very sharp at what you do. You hope your accountant and your surgeon are both known for their acumen ."}]},"collocations":{"phrases":["ADJ. considerable, great | business, commercial, critical, financial, political","VERB + ACUMEN demonstrate, show He had demonstrated considerable business acumen."]},"media":{"uk":"media/ldoce/hwd/bre/0/acumen0205.mp3","us":"media/ldoce/hwd/ame/2/acumen.mp3"},"examples":[{"en":"business/commercial/financial acumen","cn":"生意上/商业上/理财精明强干"}],"oxford":{"phon":"ˈækjəmən","pos":"noun","senses":[{"en":"the ability to understand and decide things quickly and well","cn":"精明；敏锐","ex":{"en":"He had demonstrated considerable business acumen.","cn":"他表现出相当强的商业头脑。"}}]}},"accumulation":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"堆积物；聚积物","en":"An accumulation of something is a large number of things which have been collected together or acquired over a period of time.","ex":{"en":"...an accumulation of experience and knowledge.","cn":"经验和知识的积累"}},{"pos":"N-UNCOUNT 不可数名词","cn":"堆积;积累;积聚","en":"Accumulation is the collecting together of things over a period of time.","ex":{"en":"...the accumulation of capital and the distribution of income","cn":"资本的积累和收入的分配"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to get things of the same type from different places and bring them together","cn":""},{"en":"to collect information from different places, or to collect crops, flowers, wood etc, especially from the ground","cn":""},{"en":"to collect something such as information in an organized way","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"An accumulation is a gathering or increase of something over time. You might cross your fingers in hopes of a large accumulation of snow, so that you get a day off of school."}]},"collocations":{"phrases":["ADJ. rapid | steady the steady accumulation of evidence by the police | slow | great, impressive, large, massive a massive accumulation of f","VERB + ACCUMULATION lead to | prevent"]},"media":{"uk":"media/ldoce/hwd/bre/d/accumulate0205.mp3","us":"media/ldoce/hwd/ame/4/accumulate.mp3"},"examples":[{"en":"an accumulation of toxic chemicals","cn":"有毒化学物质的积聚"},{"en":"the accumulation of wealth","cn":"财富的积累"}],"oxford":{"phon":"əˌkjuːmjəˈleɪʃn","pos":"noun","senses":[{"en":"the process of gradually increasing or getting more and more of something over a period of time","cn":"积累；积聚","g":"[uncountable]","ex":{"en":"the accumulation of wealth","cn":"财富积累"}},{"en":"an amount of something that has gradually increased over a period of time","cn":"聚积物；累积物","g":"[countable]","ex":{"en":"an accumulation of toxic chemicals","cn":"有毒化学物质的积聚"}}]}},"accord":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（国家、团体之间的正式）协定，协议，条约","en":"An accord between countries or groups of people is a formal agreement, for example to end a war.","ex":{"en":"...a fitting way to celebrate the peace accord.","cn":"庆祝和平协定的恰当的方式"}},{"pos":"VERB 动词","cn":"使受到，给予（某种待遇）","en":"If you are accorded a particular kind of treatment, people act towards you or treat you in that way.","ex":{"en":"His predecessor was accorded an equally tumultuous welcome","cn":"他的前任受到了同样热烈的欢迎。"}},{"pos":"VERB 动词","cn":"（与…）一致，符合","en":"If one fact, idea, or condition accords with another, they are in agreement and there is no conflict between them.","ex":{"en":"Such an approach accords with the principles of socialist ideology.","cn":"这种方法与社会主义意识形态的原则相符。"}},{"pos":"PHRASE 短语","cn":"（与…）一致；（与…）相符","en":"If one person, action, or fact is in accord with another, they are in agreement and there is no conflict between them. You can also say that two people or things are in accord.","ex":{"en":"...this military action, taken in accord with United Nations resolutions","cn":"依据联合国决议而采取的本次军事行动"}},{"pos":"PHRASE 短语","cn":"自动地;不借助外力地","en":"If something happens of its own accord, it seems to happen by itself, without anyone making it happen.","ex":{"en":"In many cases the disease will clear up of its own accord.","cn":"这种病很多情况下会自愈。"}},{"pos":"PHRASE 短语","cn":"自愿地；主动地","en":"If you do something of your own accord, you do it because you want to, without being asked or forced.","ex":{"en":"He did not quit as France's prime minister of his own accord.","cn":"他辞去法国总理职务并非出于自愿。"}},{"pos":"PHRASE 短语","cn":"一致地；一致同意地","en":"If a number of people do something with one accord, they do it together or at the same time, because they agree about what should be done.","ex":{"en":"With one accord they turned and walked back over the grass.","cn":"他们步调一致地转身走过草坪。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"without being asked or forced to do something","cn":"出于自愿﹐主动地"},{"en":"a situation in which two people, ideas, or statements agree with each other","cn":"相符﹐一致"},{"en":"a formal agreement between countries or groups","cn":"正式协议"}]},"vocab":{"pos":"1 n v 2 v","senses":[{"en":"If you clean your room of your own accord , you parents will be pleased—it means you did it without having to be asked. They might even accord you an extra privilege. Warring nations make peace accords ."}]},"collocations":{"phrases":["ADV. fully","PREP. with His version of events does not accord fully with the facts."]},"media":{"uk":"media/ldoce/hwd/bre/0/accord_n0205.mp3","us":"media/ldoce/hwd/ame/4/accord1.mp3"},"examples":[{"en":"The two sides signed a peace accord last July.","cn":"在刚过去的七月，双方签订了和平条约。"},{"en":"Our society accords great importance to the family.","cn":"我们的社会赋予家庭十分重要的地位。"}],"oxford":{"phon":"əˈkɔːd","pos":"noun","senses":[{"en":"a formal agreement between two organizations, countries, etc.","cn":"协议；条约","ex":{"en":"The two sides signed a peace accord last July.","cn":"在刚过去的七月，双方签订了和平条约。"}},{"en":"to give somebody/something authority, status or a particular type of treatment","cn":"给予，赠予，授予（权力、地位、某种待遇）","ex":{"en":"Our society accords great importance to the family.","cn":"我们的社会赋予家庭十分重要的地位。"},"pos":"verb"}]}},"accompanying":{"vocab":{"pos":"adj","senses":[{"en":"Someone or something that goes along with something else is accompanying. There are pictures accompanying texts; grandparents accompanying grandchildren; graphs accompanying reports."}]},"oxford":{"phon":"əˈkʌmpəniɪŋ","pos":"adjective","senses":[{"en":"provided with something else","cn":"附带的","ex":{"en":"The curator of the exhibition also wrote the accompanying catalogue.","cn":"展览的策划人还编写了介绍展览的目录。"}}]}}});
